window.DOSIK=window.DOSIK||{};DOSIK["nm_civil"]={"1":[{"t":"table","title":"법원·권리능력·성년","head":["항목","내용"],"rows":[["법원","민사에 관하여 법률에 규정이 없으면 관습법, 관습법이 없으면 조리에 의한다(제1조)"],["관습법","거듭된 관행이 법적 확신을 얻은 것이다"],["사실인 관습","법원이 아니어서 당사자가 주장·증명해야 하며 임의규정이 있을 때 법률행위 해석기준이 된다"],["신의칙","신의칙상 작위의무, 사용자의 구상권 제한, 상계권 남용 제한(주관적 요건 불요)이 판례로 인정된다"],["권리능력","태아는 사인증여를 받을 수 없고, 법인은 포괄적 유증을 받을 수 있으며 반려동물은 권리주체가 아니다"],["실종선고","보통실종 5년, 특별실종 1년이고 실종기간이 만료한 때에 사망한 것으로 본다(제27조·제28조)"],["동시사망","동일한 위난으로 2인 이상 사망하면 동시에 사망한 것으로 추정한다(제30조)"],["성년","19세로 성년이 되고 출생일을 산입하므로 2018.12.1. 출생자는 2037.12.1. 0시에 성년이다"],["권리만 얻거나 의무만 면하는 행위","(채무면제 승낙)는 단독으로 확정 유효이고, 처분 허락은 묵시적으로도 가능하다"],["영업 허락","그 영업에 관한 법정대리인의 대리권은 소멸한다(제8조)"],["동의를 받아 법률행위를 한 뒤","동의를 취소할 수 없다"]]},{"t":"vs","title":"후견","cols":[{"name":"성년후견","items":["성년후견 심판 때 가정법원은 취소할 수 없는 법률행위의 범위를 정할 수 있고, 일상생활에 필요하고 대가가 과도하지 않은 행위는 취소할 수 없다"]},{"name":"한정후견","items":["본인의 의사를 고려하여야 한다"]},{"name":"특정후견","items":["본인의 의사에 반하여 할 수 없다"]}]},{"t":"table","title":"취소권과 속임수","head":["항목","내용"],"rows":[["제한능력자의 취소","단독으로 취소할 수 있고 재판 외 의사표시로도 취소한다"],["취소 후 반환범위","법정대리인의 선의·악의와 관계없이 현존이익이다(제141조)"],["상대방의 철회권","계약 당시 제한능력자임을 알았으면 인정되지 않는다(제16조)"],["확답촉구","1개월 이상의 기간을 정해 한다(제15조)"],["후견의 공시","가족관계등록부가 아니라 후견등기부에 공시한다"],["속임수(제17조)","제한능력자가 속임수로 능력자로 믿게 하면 취소할 수 없다"],["동의가 있는 것으로 믿게 한 경우","미성년자와 피한정후견인만 해당하므로, 피성년후견인은 그런 속임수를 써도 취소할 수 있다"],["미성년자가 동의 없음을 이유로 취소","신의칙 위반이 아니다"]]},{"t":"table","title":"법인과 비법인사단","head":["항목","내용"],"rows":[["이사의 대표권 제한","정관에 기재해야 효력이 있고 등기하지 않으면 제3자에게 대항하지 못한다(제60조)"],["이사의 대리","정관·총회가 금지하지 않은 사항에 한해 특정한 행위만 대리하게 할 수 있고 포괄적 위임은 효력이 없다(제62조)"],["임시이사","정식이사와 같은 권한을 가지며 비법인사단에도 유추적용된다"],["해임사유","정관에 해임사유를 정했으면 다른 사유로 해임할 수 없다"],["대표기관(제35조)","사실상 대표하여 사무를 집행하는 사람도 포함된다"],["외형상 직무행위","직무범위에 속하지 않음을 피해자가 알았거나 중대한 과실로 몰랐으면 법인은 책임을 지지 않는다"],["제35조","비법인사단 대표자의 불법행위에도 적용된다"],["총유재산 보존행위의 소","구성원 개인이 총회 결의를 거쳐도 단독으로 제기할 수 없다"],["타인 채무 보증","총유물 관리·처분행위가 아니어서 총회 결의 없이 해도 유효하다"],["교회","분열이 인정되지 않아 재산은 잔존 교인의 총유이고, 성년 여자도 종원이 된다"],["청산인","채권신고기간 내 변제하지 못하지만 법인은 지연손해 배상의무를 면하지 못하며(제90조), 알고 있는 채권자는 청산에서 제외하지 못한다"],["청산종결등기","청산사무가 남아 있으면 법인은 소멸하지 않는다"]]}],"2":[{"t":"table","title":"동산·부동산·수목","head":["항목","내용"],"rows":[["부동산","토지와 그 정착물은 부동산이고 부동산 외의 물건은 모두 동산이다(제99조)"],["전기","관리할 수 있는 전기도 동산이다"],["건물의 개수","공부상 등록이 아니라 소유자의 의사 등 주관적 사정을 참작해 사회통념으로 정한다"],["수목","입목법에 따라 등기된 수목이나 명인방법을 갖춘 수목은 토지와 별개로 거래된다"],["권원 없이 남의 토지에 심은 수목","계속 관리하더라도 토지에 부합한다"],["유동집합물","특정할 수 있으면 증감·변동하는 유동집합물도 하나의 물건이 된다"]]},{"t":"table","title":"종물","head":["항목","내용"],"rows":[["종물","주물의 상용에 이바지하는 독립한 물건으로서 원칙적으로 주물 소유자의 물건이어야 한다(제100조 제1항)"],["종물의 요건","주물 자체의 효용을 도와야 하고, 소유자나 이용자의 상용에 쓰일 뿐인 물건은 종물이 아니다"],["부동산","부동산도 종물이 될 수 있고, 주유소 지하에 매설한 유류저장탱크는 토지의 종물이 아니다"],["제100조 제2항","임의규정이므로 특약으로 종물을 처분에서 뺄 수 있다"],["적용 범위","압류 같은 공법상 처분에도 적용되고, 건물과 그 부지의 토지임차권, 원본채권과 이자채권처럼 권리 상호간에도 유추적용된다"],["이자채권","원본채권을 양도해도 이미 변제기에 이른 이자채권은 함께 넘어가지 않는다"]]},{"t":"vs","title":"과실","cols":[{"name":"천연과실","items":["물건의 용법에 따라 수취하는 산출물이다(제101조)","원물에서 분리하는 때 수취권자에게 속한다(제102조)"]},{"name":"법정과실","items":["물건의 사용대가로 받는 금전 등이다(제101조)","존속기간 일수 비율로 취득한다(제102조)","임대료는 법정과실이다"]},{"name":"과실이 아닌 것과 매매목적물","items":["국립공원 입장료나 특허권 사용료는 물건의 사용대가가 아니어서 과실이 아니다","목적물을 인도하기 전이고 매수인이 대금을 완제하지 않았다면 매도인이 이행지체 중이어도 목적물에서 생긴 과실은 매도인에게 속한다(제587조 관련 판례)"]}]},{"t":"def","term":"유체","text":"피상속인이 유언으로 자신의 유체를 처분했더라도 제사주재자가 이에 따라야 할 법적 의무는 없다 · 유체의 귀속은 제사주재자에게 있다"}],"3":[{"t":"vs","title":"반사회질서","cols":[{"name":"무효","items":["도박자금 대여","보험금 부정취득 목적의 다수 보험계약","부첩관계 종료를 해제조건으로 한 증여"]},{"name":"제103조 위반이 아님","items":["뇌물의 소극적 은닉을 위한 임치","강제집행을 피하려는 허위 근저당권 설정","해외파견 비용 반환 약정","민사사건 성공보수 약정"]},{"name":"무효의 효과","items":["증언 대가 약정은 통상 용인되는 수준을 넘을 때만 무효이다","무효는 선의의 제3자에게도 주장할 수 있으며 추인으로 유효가 되지 않는다"]}]},{"t":"table","title":"이중매매·불공정·허위표시","head":["항목","내용"],"rows":[["이중매매","제2매수인이 이중매매 사실을 안 것만으로는 부족하고 매도인의 배임행위에 적극 가담해야 반사회적 법률행위가 된다"],["이 경우","절대적 무효이므로 제2매수인에게서 다시 산 제3자는 선의라도 소유권을 얻지 못한다"],["제1매수인","제2매수인에게 직접 말소를 청구하지 못하고 매도인을 대위하여 청구한다"],["불공정한 법률행위(제104조)","궁박·경솔·무경험과 급부 간 현저한 불균형이 필요하고, 폭리자가 그 사정을 알고 이용하려는 의사가 있어야 한다"],["불균형 판단","객관적 가치로, 판단 시점은 법률행위 당시다"],["무경험","거래일반의 경험부족이다"],["궁박·경솔·무경험의 기준","궁박은 본인, 경솔·무경험은 대리인을 기준으로 하며 현저한 불균형이 있어도 궁박 등은 추정되지 않는다"],["불공정과 경매","경매에는 적용되지 않는다"],["불공정의 추인과 전환","추인으로 유효가 될 수 없으나 무효행위 전환(제138조)은 가능하며 그 계약의 부제소합의도 무효다"],["비진의표시의 진의","특정 내용의 의사표시를 하려는 생각이지 마음속 바람이 아니다"],["사직서","경영방침에 따른 사직서 제출 후 즉시 재입사는 비진의표시이고, 희망퇴직 권고를 받고 숙고해 낸 사직서는 아니다"],["통정허위표시","상대방과의 합의가 필요하며 무효이지만 사해행위 취소의 대상이 된다"],["제108조 제2항의 제3자","선의면 족하고 무과실은 필요 없으며 선의가 추정된다"],["제3자에 포함","가압류권자, 파산관재인(채권자 일부라도 선의면 선의), 악의자로부터의 선의 전득자가 포함된다"]]},{"t":"table","title":"착오·사기·강박과 대리","head":["항목","내용"],"rows":[["착오","법률행위 내용의 중요부분 착오면 취소할 수 있고 중대한 과실은 상대방이 증명한다(제109조)"],["중요부분","경제적 불이익이 없으면 중요부분이 아니고, 동기는 법률행위 내용으로 삼았으면 취소 대상이다"],["착오 취소 가능","법률의 착오, 매도인이 해제한 뒤, 하자담보책임이 성립할 때도 착오 취소가 가능하지만 소송행위는 취소할 수 없다"],["경과실 착오","경과실로 착오한 자가 취소해도 신뢰이익 배상책임은 없고, 제109조 배제 특약은 유효하다"],["사기·강박","사기는 기망의 위법성, 강박은 강박의 고의가 요건이다"],["대리인의 기망","제3자의 사기가 아니어서 본인이 몰랐어도 상대방이 취소할 수 있다"],["권한을 정하지 않은 대리인","보존행위와 성질을 바꾸지 않는 이용·개량행위만 한다(제118조)"],["대리인이 여럿","각자대리가 원칙이다(제119조)"],["매도 대리권","중도금·잔금 수령과 지급기일 연장 권한이 있지만 합의해제·해제권·의사표시 수령권은 없다"],["복대리","임의대리인은 본인 승낙이나 부득이한 사유가 있어야 복대리인을 선임한다(제120조)"],["대리권 소멸","원인된 법률관계가 끝나면 대리권이 소멸한다(제128조)"],["착오·사기·강박 유무","대리인 기준이다(제116조)"],["대리인의 능력","행위능력자일 필요가 없다(제117조)"],["해제 시 원상회복의무","본인이 진다"]]},{"t":"table","title":"표현대리·무효·조건","head":["항목","내용"],"rows":[["제125조","상대방이 선의·무과실이어야 하고 직함 사용 묵인으로도 수여표시가 인정된다"],["제126조의 정당한 이유","대리행위 당시 기준이고 기본대리권과 같은 종류일 필요가 없으며 복임권 없는 대리인이 선임한 복대리인의 권한이나 소멸한 대리권도 기본대리권이 된다"],["표현대리 성립","과실상계로 책임을 줄일 수 없고, 강행법규 위반 행위에는 성립하지 않는다"],["무권대리인 책임(제135조)","무과실책임이고 이행·손해배상 선택권은 상대방에게 있으며 제한능력자는 지지 않는다"],["일부 추인","상대방 동의가 없으면 무효이고, 악의의 상대방도 최고는 할 수 있으나 철회는 못 한다"],["무권대리인이 본인을 단독상속한 뒤","추인을 거절하는 것은 신의칙에 반한다"],["일부무효","전부무효가 원칙이고(제137조), 무효임을 알고 추인하면 새로운 법률행위로 본다(제139조)"],["무효행위 추인","무효원인이 소멸한 후에 하며 강박으로 취소된 행위도 추인할 수 있다"],["법정추인 사유","이행·이행청구·경개·담보제공·양도·강제집행이고 이의를 보류하면 추인이 아니다(제145조)"],["취소권","추인할 수 있는 날부터 3년, 법률행위를 한 날부터 10년 내에 행사하며 이는 제척기간이다(제146조)"],["토지거래허가 전 유동적 무효 상태","계약금 배액 상환 해제는 되지만 채무불이행 해제나 계약금 부당이득 반환청구는 안 되고, 협력의무는 소로 구할 수 있다"],["정지조건·해제조건","정지조건은 성취한 때부터 효력이 생기고 해제조건은 성취한 때부터 효력을 잃으며 소급 의사표시가 있으면 그에 따른다(제147조)"],["불법조건","법률행위 전부가 무효다"],["기성조건","정지조건이면 조건 없는 법률행위, 해제조건이면 무효이고, 불능조건은 그 반대다(제151조)"],["조건 의사","묵시적으로도 표시할 수 있으나 표시되지 않으면 동기에 불과하고, 반드시 실현될 사실은 조건이 아니라 기한이다"],["기한","채무자의 이익으로 추정하며(제153조), 기한이익 상실특약은 형성권적 특약으로 추정한다"],["기한이익 상실 사유","담보 손상·감소·멸실, 담보제공 의무 불이행"]]}],"4":[{"t":"table","title":"기간 계산","head":["항목","내용"],"rows":[["일·주·월·연으로 정한 기간","초일을 산입하지 않고 오전 0시부터 시작하면 산입한다(제157조)"],["주·월·연","역에 따라 계산하며 처음부터 기산하지 않으면 최후의 주·월·연에서 기산일에 해당한 날의 전일로 만료한다(제160조)"],["말일이 토요일 또는 공휴일","그 익일로 만료한다(제161조)"],["분·시간으로 정한 기간","즉시 기산한다"],["나이","출생일을 산입해 만 나이로 계산하고 1세 미만은 월수로 표시할 수 있다(제158조)"],["정년 60세","60세에 도달하는 날을 말한다"],["거꾸로 세는 기간","선거일 전 3년간처럼 초일 불산입 원칙을 따라 선거일 전날부터 센다"]]},{"t":"table","title":"시효기간과 기산점","head":["항목","내용"],"rows":[["채권","10년"],["채권·소유권 외의 재산권","20년이다(제162조)"],["3년","이자·급료 등 1년 이내 정기급부, 의사·약사의 치료 채권, 도급받은 자의 공사 채권은 3년(제163조)"],["1년","음식료·숙박료, 동산 사용료, 노역인·연예인 임금은 1년이다(제164조)"],["확정된 채권","판결·지급명령·화해 등으로 확정된 채권은 단기시효라도 10년이 된다(제165조)"],["근로계약상 보호의무 위반에 따른 손해배상청구권","10년이다"],["기산점","권리를 행사할 수 있는 때부터 진행하며 권리의 존재를 몰랐다는 사실상 장애는 진행을 막지 않는다(제166조)"],["부작위 채권","위반행위를 한 때부터"],["동시이행항변권이 붙은 대금채권","지급기일부터 진행한다"],["정지조건부 권리","조건 성취 전에는 진행하지 않는다"],["부동산을 인도받아 점유하는 매수인의 등기청구권","시효로 소멸하지 않는다"]]},{"t":"table","title":"시효의 중단","head":["항목","내용"],"rows":[["중단사유","청구, 압류·가압류·가처분, 승인이 중단사유다(제168조)"],["소가 각하·기각·취하","중단 효력이 없지만 최고의 효력은 남아 6월 내에 재판상 청구 등을 하면 최초 청구 때 중단된 것으로 본다(제170조)"],["최고를 거듭하다 소를 제기","소 제기 시부터 소급해 6월 이내에 한 최고 때 중단된다(제174조)"],["그 밖의 중단 사유","대항요건을 갖추지 못한 양수인의 소, 형사 배상명령 신청, 확정판결 후 재판상 청구 확인의 소도 중단 사유다"],["승인","처분의 능력이나 권한이 필요 없다(제177조)"],["계속적 거래의 여러 채무 중 일부를 변제","전부에 대해 승인이 된다"],["이행인수인이 한 승인","효력이 없다"],["여러 채권 중 하나를 행사","다른 채권은 중단되지 않는다"],["재판상 청구로 중단된 시효","재판이 확정된 때부터 새로 진행한다(제178조)"],["가압류의 중단 효력","집행보전 효력이 있는 동안 계속되며 본압류로 이행해도 소멸하지 않는다"]]},{"t":"table","title":"시효 완성·보증·제척기간","head":["항목","내용"],"rows":[["시효 완성의 효과","기산일에 소급해 효력이 생긴다(제167조)"],["완성의 주장","당사자가 원용해야 하며 법원이 직권으로 고려하지 않는다"],["원금이 시효로 소멸","그 전에 생긴 이자·지연손해금도 소멸한다"],["시효이익의 포기","미리 포기하지 못하고 완성 후에는 포기할 수 있으며 그때부터 새 시효가 진행한다"],["시효의 배제·연장·가중","법률행위로 할 수는 없고 단축·경감은 할 수 있다(제184조)"],["주채무자의 시효이익 포기","보증인에게 효력이 없다"],["연대보증채무의 시효중단","주채무를 중단시키지 않으며 주채무가 시효로 소멸하면 보증채무는 자체 중단에도 부종성에 따라 소멸한다"],["부종성을 부정할 특별한 사정이 있으면","보증인은 주채무 시효소멸을 주장할 수 없다"],["제척기간","중단이 없고 원칙적으로 권리가 발생한 때부터 기산하며 법원이 직권으로 조사한다"],["매매예약완결권","행사기간 약정이 없으면 예약 성립 시부터 10년이 지나면 소멸한다"],["제척기간이 지난 채권","그 전에 상계적상에 있었으면 자동채권으로 상계할 수 있다"]]}],"5":[{"t":"table","title":"물권변동","head":["항목","내용"],"rows":[["물권법정주의","물권은 법률 또는 관습법에 의하는 외에는 임의로 창설하지 못한다(제185조)"],["관습법으로 인정된 물권","관습법상 법정지상권과 분묘기지권"],["법률행위로 인한 부동산 물권변동","등기해야 효력이 생긴다(제186조)"],["법률의 규정에 의한 취득","상속·공용징수·판결·경매 등은 등기 없이 효력이 생기지만 등기하지 않으면 처분하지 못한다(제187조)"],["제187조의 판결","형성판결만을 말한다"],["동산 물권의 양도","인도해야 효력이 생긴다(제188조 제1항)"],["인도의 종류","현실인도 외에 간이인도, 점유개정, 목적물반환청구권의 양도가 있다"]]},{"t":"table","title":"물권적 청구권과 혼동","head":["항목","내용"],"rows":[["소유자의 청구","점유자에게 반환을, 방해자에게 방해제거를, 방해할 염려가 있는 자에게 예방이나 손해배상의 담보를 청구할 수 있다(제213조·제214조)"],["점유할 권리가 있는 자","반환을 거부할 수 있다"],["물권적 청구권","소유권과 분리해 양도하지 못한다"],["혼동","같은 물건에 대한 소유권과 다른 물권이 한 사람에게 귀속하면 다른 물권은 소멸한다"],["혼동의 예외","그 물권이 제3자의 권리의 목적이 된 때에는 소멸하지 않는다(제191조)"]]}],"6":[{"t":"table","title":"점유","head":["항목","내용"],"rows":[["점유권","물건을 사실상 지배하는 자는 점유권이 있다(제192조)"],["점유의 추정","점유자는 소유의 의사로 선의·평온·공연하게 점유한 것으로 추정하고(제197조 제1항), 점유자가 행사하는 권리는 적법하게 보유한 것으로 추정한다(제200조)"],["본권에 관한 소에 패소","선의의 점유자도 소가 제기된 때부터 악의로 본다"],["과실","선의 점유자는 과실을 취득하고 악의 점유자는 과실을 반환하거나 대가를 보상한다(제201조)"],["점유물 멸실·훼손","악의 점유자는 손해 전부, 선의 점유자는 현존이익 한도에서 배상하되 소유의 의사가 없으면 선의여도 전부 배상한다(제202조)"],["필요비","청구할 수 있으나 과실을 취득했으면 통상의 필요비는 청구하지 못한다(제203조)"],["점유를 침탈당하면","반환과 손해배상을 침탈당한 날부터 1년 내에 청구한다(제204조)"],["침탈자의 특별승계인","악의일 때만 행사할 수 있다"],["방해제거 청구","방해가 끝난 날부터 1년 내에 한다(제205조)"]]},{"t":"table","title":"취득시효와 선의취득","head":["항목","내용"],"rows":[["부동산 취득시효","20년간 소유의 의사로 평온·공연하게 점유하고 등기해야 소유권을 취득한다"],["등기부취득시효","소유자로 등기된 자가 10년간 선의·무과실로 점유하면 된다(제245조)"],["동산 취득시효","10년, 선의·무과실로 개시하면 5년이다(제246조)"],["선의취득","평온·공연하게 동산을 양수한 자가 선의·무과실로 점유하면 양도인이 무권리자여도 즉시 소유권을 취득한다(제249조)"],["도품·유실물","도난·유실한 날부터 2년 내 반환청구할 수 있으나 금전은 예외다(제250조)"],["부동산","선의취득이 없다"]]},{"t":"table","title":"공유","head":["항목","내용"],"rows":[["공유지분","균등한 것으로 추정한다(제262조)"],["지분 처분","자유이다"],["공유물 처분·변경","전원 동의, 관리는 지분의 과반수, 보존행위는 각자 한다(제264조·제265조)"],["분할금지 약정","5년 내로만 할 수 있다(제268조)"],["합유물 처분·변경","합유자 전원의 동의가 필요하다(제272조)"]]}],"7":[{"t":"table","title":"지상권","head":["항목","내용"],"rows":[["지상권의 최단 존속기간","견고한 건물이나 수목은 30년, 그 밖의 건물은 15년, 건물 외 공작물은 5년보다 짧게 정하지 못한다(제280조)"],["기간을 정하지 않으면","그 최단기간으로 한다"],["공작물 종류를 정하지 않으면","그 밖의 건물 소유 목적으로 본다(제281조)"],["지상권 소멸 시","건물 등이 남아 있으면 지상권자는 갱신을 청구할 수 있고, 설정자가 거절하면 공작물·수목의 매수를 청구할 수 있다(제283조)"],["원상회복의무","지상권자는 원상회복의무가 있지만 설정자가 상당한 가액으로 매수를 청구하면 정당한 이유 없이 거절하지 못한다(제285조)"],["법정지상권","저당물 경매로 토지와 지상건물의 소유자가 달라지면 건물소유자에게 지상권을 설정한 것으로 본다(제366조)"],["지료","당사자의 청구로 법원이 정한다"],["관습법상 법정지상권","동일인 소유였던 토지·건물이 매매 등으로 소유자가 달라질 때 인정된다"]]},{"t":"table","title":"지역권과 전세권","head":["항목","내용"],"rows":[["지역권","타인의 토지를 자기 토지의 편익에 이용하는 권리다(제291조)"],["지역권의 이전","요역지 소유권에 부종해 이전하고 요역지와 분리해 양도하지 못한다(제292조)"],["지역권의 시효취득","계속되고 표현된 것에 한해 시효취득할 수 있다(제294조)"],["전세권자","부동산을 사용·수익하고 전세금 우선변제를 받으며 농경지는 목적으로 하지 못한다(제303조)"],["존속기간","10년을 넘지 못하고 건물 전세권을 1년 미만으로 정하면 1년으로 한다(제312조)"],["기간을 정하지 않으면","소멸 통고 후 6월이 지나면 소멸한다(제313조)"],["전세금 반환이 지체되면","경매를 청구할 수 있다(제318조)"]]}],"8":[{"t":"table","title":"유치권과 질권","head":["항목","내용"],"rows":[["유치권","타인의 물건을 점유한 자가 그 물건에 관하여 생긴 채권이 변제기에 있으면 변제받을 때까지 유치할 수 있다"],["점유가 불법행위로 시작되면","성립하지 않는다(제320조)"],["불가분성","채권 전부를 변제받을 때까지 유치물 전부에 행사한다(제321조)"],["성립","등기 없이 성립하는 법정담보물권이다"],["유치권자의 의무","선량한 관리자의 주의로 점유하고 채무자 승낙 없이 사용·대여·담보제공을 하지 못하며 보존에 필요한 사용은 할 수 있다(제324조)"],["위반하면","채무자가 소멸을 청구할 수 있다"],["채무자","상당한 담보를 제공하고 유치권 소멸을 청구할 수 있다(제327조)"],["질권 설정","목적물을 인도해야 효력이 생기며(제330조), 점유개정으로는 설정할 수 없다"],["전질","질권자는 자기 책임으로 전질할 수 있다(제336조)"],["물상대위","질물의 멸실 등으로 설정자가 받을 금전에 물상대위할 수 있으나 지급·인도 전에 압류해야 한다(제342조)"]]},{"t":"table","title":"저당권","head":["항목","내용"],"rows":[["저당권","점유를 옮기지 않고 부동산에서 우선변제를 받는 권리다(제356조)"],["효력 범위","부합물과 종물에 미치고(제358조), 과실에는 압류 후에 미친다(제359조)"],["지연배상","원본 이행기일을 지난 후 1년분에 한해 담보한다(제360조)"],["근저당","최고액만 정하고 채무 확정을 장래에 보류하며 이자는 최고액에 산입한 것으로 본다(제357조)"],["일괄경매","토지 저당 후 설정자가 건물을 지으면 저당권자는 건물도 함께 경매할 수 있지만 건물 대가에서는 우선변제를 받지 못한다(제365조)"],["공동저당 동시배당","같은 채권을 위해 여러 부동산에 저당권을 설정하고 동시에 배당하면 각 부동산 경매대가에 비례해 분담한다"],["일부만 먼저 배당","그 대가에서 전액을 받을 수 있고 차순위 저당권자는 대위할 수 있다(제368조)"]]}],"9":[{"t":"table","title":"채권의 목적","head":["항목","내용"],"rows":[["특정물 인도채무자","인도할 때까지 선량한 관리자의 주의로 보존하며(제374조), 임차목적물 반환채무도 특정물채무다"],["종류채권","품질을 정할 수 없으면 중등품질로 이행하고, 이행에 필요한 행위를 완료하거나 채권자 동의로 지정하면 그 물건으로 특정된다(제375조)"],["선택채권의 선택권","다른 정함이 없으면 채무자에게 있고(제380조) 선택은 채권 발생 시로 소급하며 제3자가 선택할 때는 채무자와 채권자에게 의사표시를 한다"],["선택할 행위 중 불능인 것","있으면 잔존한 것에 존재한다(제385조)"],["다른 나라 통화로 지급할 채권","그 나라의 각종 통화로 변제할 수 있고(제377조)"],["우리나라 통화로 갚을 때","이행기가 아니라 현실 지급 시의 환금시가로 환산한다(제378조)"],["법정이율","민사 법정이율은 연 5푼(5%), 상사는 연 6%다"],["금전","금전도 특정물채권의 목적이 될 수 있다"]]},{"t":"table","title":"이행지체와 이행불능","head":["항목","내용"],"rows":[["확정기한","기한이 도래한 때"],["불확정기한","도래함을 안 때"],["기한이 없으면","이행청구를 받은 때부터 지체책임을 진다(제387조)"],["지시채권·무기명채권·양도성예금증서","증서를 제시한 때부터 지체가 된다"],["반환시기 약정이 없는 소비대차","상당한 기간을 정해 최고하고 그 기간이 지나야 지체가 된다"],["불법행위 손해배상채무","최고 없이 불법행위 시부터 지체가 된다"],["확정된 지연손해금채무","이행청구를 받은 때부터 지체가 된다"],["이중매매","제2매수인에게 소유권이전등기를 마친 때 이행불능이 되고, 계약 체결만으로는 불능이 아니다"],["불능이 아닌 경우","가압류 집행이나 강제경매 진행 중이라는 사정만으로도 불능이 아니며, 증여 대상 권리가 타인에게 있다는 것만으로도 불능이 아니다"],["이행보조자","고의·과실은 채무자의 것으로 보고(제391조), 호의로 이행한 제3자도 채무자가 용인했으면 이행보조자다"]]},{"t":"table","title":"손해배상","head":["항목","내용"],"rows":[["통상손해","한도로 하고 특별손해는 채무자가 그 사정을 알았거나 알 수 있었을 때만 배상하며(제393조)"],["판단 시점","계약 체결 당시가 아니라 채무불이행 당시다"],["이행불능 후 가격 상승분","특별손해이고 배상액은 이행불능 당시 시가가 기준이다"],["영업용 건물 일부 멸실의 휴업손해","통상손해다"],["손해배상청구권의 시효","채무불이행 시부터 진행한다"],["신뢰이익","이행이익을 넘을 수 없다"],["과실상계","채권자에게 과실이 있으면 법원은 직권으로 참작하며 당사자가 주장한 비율에 구속되지 않는다(제396조)"],["본래 급부의 이행청구","과실상계가 적용되지 않는다"],["순서","과실상계를 먼저 하고 손익상계를 나중에 한다"],["일부청구","손해 전액에서 과실비율로 감액한 잔액이 청구액을 넘지 않으면 그 잔액을 인용한다"],["금전채무 불이행의 배상액","법정이율, 약정이율이 있으면 그 이율에 따르고 채권자는 손해를 증명할 필요가 없으며 채무자는 과실 없음을 항변하지 못한다(제397조)"],["지연손해금","이자가 아니라 손해배상금이므로 3년 단기시효가 적용되지 않는다"],["지연손해금 비율 약정","손해배상액의 예정으로서 감액 대상이 된다"]]},{"t":"table","title":"배상액 예정과 채권자지체","head":["항목","내용"],"rows":[["채권자","채무불이행 사실만 증명하면 되고 손해 발생과 액수는 증명할 필요가 없다"],["채무자","손해가 없었다는 증명으로는 면책되지 않지만 귀책사유 없음을 증명하면 면책된다"],["실손해가 더 커도","초과분이나 특별손해를 따로 청구하지 못하고, 예정은 불법행위 손해까지 포함하지 않으며 과실상계도 하지 않는다"],["부당히 과다하면","법원이 감액하고(제398조), 위약금 약정은 예정으로 추정한다"],["위약벌","감액할 수 없고 공서양속 위반 범위에서만 무효다"],["근로계약","위약금·배상액 예정이 금지된다"],["채권자지체","법정책임이어서 채권자의 귀책사유가 필요 없다"],["채권자의 행위가 필요한 채무","구두의 제공으로 충분하다"],["지체 중 채무자","고의 또는 중대한 과실이 없으면 책임이 없고(제401조), 보관·변제 비용 증가분은 채권자 부담이다(제403조)"],["수령의무","채권자에게 수령의무가 없으므로 채권자지체만으로 채무불이행책임을 묻지는 못한다"]]}],"10":[{"t":"table","title":"채권자대위권의 대상","head":["항목","내용"],"rows":[["피보전채권","금전채권 보전에는 채무자의 무자력이 필요하지만 소유권이전등기청구권 같은 특정채권 보전에는 필요 없다"],["물권적 청구권","피보전권리가 된다"],["임차인","임차권 보전을 위해 임대인의 제3자에 대한 인도청구권을 대위할 수 있으나, 임대인 동의 없는 임차권 양수인은 임대인의 권리를 대위하지 못한다"],["피보전채권의 존부","법원의 직권조사사항이다"],["일신에 전속한 권리","대위하지 못한다(제404조 제1항)"],["일신전속권이 아닌 것","조합원의 조합탈퇴권, 임대인의 해지권은 일신전속권이 아니어서 대위할 수 있다"],["대위 대상","채권자대위권, 채권자취소권, 토지거래허가 협력의무 이행청구권도 대위 대상이다"]]},{"t":"table","title":"대위의 행사","head":["항목","내용"],"rows":[["피보전채권의 기한 전","법원의 허가가 있어야 하고 보전행위는 허가 없이 한다(제404조 제2항)"],["금전·동산 인도","제3채무자에게 대위채권자 자신에게 직접 이행하라고 청구할 수 있다"],["보전행위 외의 권리 행사","채무자에게 통지하고, 통지 후 채무자의 처분은 채권자에게 대항하지 못한다(제405조)"],["제3채무자","채무자에 대해 가진 동시이행항변권 등으로 대위채권자에게 대항할 수 있다"],["시효 항변","채권자의 채무자에 대한 채권이 시효로 소멸했다는 항변은 제3채무자가 원용하지 못한다"]]},{"t":"table","title":"채권자취소권의 요건","head":["항목","내용"],"rows":[["피보전채권","금전채권이어야 하고 특정물 이전등기청구권은 원칙적으로 피보전채권이 아니다"],["사해행위 전 성립","사해행위 전에 성립한 채권이어야 하지만 기초 법률관계가 있고 성립 개연성이 높으면 이후 채권도 된다"],["정지조건부 채권","피보전채권이 된다"],["양수인","사해행위 전 성립 채권을 사해행위 후 양수하거나 대항요건을 사해행위 후에 갖춘 양수인도 행사할 수 있다"],["사해행위가 될 수 있는 것","상속재산 분할협의, 시효이익 포기, 통정허위표시"],["사해행위가 아닌 것","채무의 본지에 따른 변제와 유일한 재산을 우선변제권 있는 채권자에게 대물변제한 경우는 원칙적으로 사해행위가 아니다"],["압류금지재산","적극재산에 넣지 않는다"]]},{"t":"table","title":"취소권의 행사와 효력","head":["항목","내용"],"rows":[["행사 방법","취소권은 재판상으로만 행사하고 피고는 수익자나 전득자이며 채무자는 피고적격이 없다"],["전득자를 상대로 해도","취소 대상은 채무자와 수익자 사이의 행위다"],["악의의 증명","채무자의 악의는 채권자가 증명하고 수익자의 악의는 추정된다"],["제척기간","취소원인을 안 날부터 1년, 법률행위가 있은 날부터 5년 내에 제기하며(제406조) 제척기간 도과는 상대방이 증명한다"],["청구 순서","취소만 먼저 구하고 원상회복을 나중에 청구할 수도 있다"],["원상회복","원상회복만 구해도 법원은 가액배상을 명할 수 있고, 제3자가 저당권을 취득했어도 그 피담보채권액을 빼지 않고 가액배상을 명한다"],["동산","취소채권자에게 직접 인도를 청구할 수 있다"],["채권양도가 취소되면","수익자에게 양도 취소 통지를 하도록 청구한다"],["취소의 효력","모든 채권자의 이익을 위해 미치지만(제407조) 사해행위 후에 성립한 채권자는 포함되지 않는다"],["채무자","취소의 효력은 채권자와 수익자 사이에서만 생겨 채무자가 권리를 다시 얻지 않으므로 채무자를 대위해 청구할 수 없다"],["수익자","피보전채권의 시효소멸을 원용할 수 있다"]]}],"11":[{"t":"table","title":"분할·불가분·연대채무","head":["항목","내용"],"rows":[["가분채무","여러 명이 가분채무를 지면 특별한 의사표시가 없는 한 균등한 분할채무가 된다(제408조)"],["불가분채무","여러 명이 타인의 재산을 함께 사용해 생긴 부당이득반환채무는 불가분채무이고, 출재로 공동면책한 불가분채무자는 다른 채무자의 부담부분을 구상할 수 있다"],["절대적 효력","이행청구(제416조), 경개(제417조), 상계(제418조 제1항), 채권자지체(제422조)는 다른 연대채무자 전원에게 효력이 있다"],["부담부분 한도의 효력","면제·혼동·소멸시효 완성(제419조~제421조)과 상계권자가 상계하지 않을 때 다른 채무자의 상계(제418조 제2항)는 그 채무자의 부담부분 한도에서만 효력이 있다"],["상대적 효력","그 밖의 사항은 상대적 효력이어서 승인이나 압류로 인한 시효중단은 다른 연대채무자에게 미치지 않는다(제423조)"],["일부 면제","일부 면제를 받은 연대채무자의 잔존 채무가 자기 부담부분 이상이면 다른 채무자의 채무는 줄지 않는다"],["잔존 채무가 부담부분보다 적어지면","그 차액만큼 다른 채무자도 면책된다"],["연대보증인","연대채무자 전원의 부탁으로 연대보증한 사람은 변제 후 어느 연대채무자에게나 전액을 구상할 수 있다"]]},{"t":"table","title":"보증채무","head":["항목","내용"],"rows":[["보증의 방식","보증인의 기명날인 또는 서명이 있는 서면으로 해야 효력이 생기고 전자적 형태는 효력이 없으며(제428조의2), 기명날인은 타인이 대행할 수 있다"],["보증채권","보증채권만 주채권과 분리해 양도할 수 없고, 주채권에 대항요건을 갖추면 보증채권에도 효력이 미친다"],["주채무가 실질적 동일성을 잃을 정도로 바뀌면","보증채무는 소멸한다"],["보증인의 항변","주채무자의 항변으로 대항할 수 있고 주채무자가 항변을 포기해도 보증인에게는 효력이 없다(제433조)"],["시효기간과 연체이율","주채무를 따르지 않고 보증채무 자체로 정한다"],["구상","부탁 없는 보증인은 그 당시 이익을 받은 한도, 주채무자의 의사에 반한 보증인은 현존이익 한도에서 구상한다(제444조)"],["이사의 보증","채무액과 변제기가 특정된 회사 채무를 보증한 이사는 사임을 이유로 해지하지 못한다"]]},{"t":"table","title":"채권양도","head":["항목","내용"],"rows":[["양도금지특약","선의의 제3자에게 대항하지 못하며 경과실로 모른 양수인은 선의로 취급한다(제449조)"],["특약이 있어도","압류·전부명령으로는 이전되고, 전부채권자에게서 양수한 자는 악의여도 채무자가 무효를 주장하지 못한다"],["임금채권 양수인","사용자에게 직접 지급을 청구할 수 없다"],["양도할 수 있는 채권","장래 채권도 특정 가능하고 발생이 기대되면 양도할 수 있고, 가압류된 채권도 양도할 수 있다"],["대항요건","양도인의 통지나 채무자의 승낙이 있어야 채무자에게 대항하고, 확정일자 있는 증서여야 채무자 외의 제3자에게 대항한다(제450조)"],["승낙","조건을 붙일 수 있다"],["이의를 보류하지 않은 승낙","이미 다른 사람에게 양도되었다는 사실로는 대항할 수 있다"],["양도통지 후 양도계약이 해제되면","양수인이 채무자에게 해제 사실을 통지해야 양도인이 대항할 수 있다"],["대항요건을 못 갖춘 양수인의 소 제기","시효중단 사유다"]]},{"t":"table","title":"채무인수","head":["항목","내용"],"rows":[["면책적 인수","채권자와 인수인의 계약에 의한 면책적 인수는 이해관계 없는 제3자가 채무자의 의사에 반해 할 수 없다"],["병존적 인수","채무자 의사에 반해서도 할 수 있다"],["채무자와 인수인의 계약","채권자의 승낙이 있어야 효력이 생기며 승낙의 상대방은 채무자나 인수인이고, 거절한 뒤에는 다시 승낙해도 효력이 없다(제454조)"],["불분명하면","면책적인지 불분명하면 병존적 인수로 보고, 병존적 인수는 제3자를 위한 계약이며 부탁받은 인수인과 채무자는 연대채무 관계다"],["면책적 인수인","전 채무자의 항변으로 대항할 수 있다"],["보증·담보","전 채무자의 채무에 대한 보증이나 제3자 제공 담보는 그들이 동의하지 않으면 소멸한다(제459조)"],["이행인수","매수인이 저당 피담보채무를 인수하고 대금에서 공제하면 원칙적으로 이행인수이고, 이행인수인이 변제하면 채권자를 법정대위할 수 있다"],["인수채무의 시효","인수일부터 새로 진행한다"]]}],"12":[{"t":"table","title":"변제","head":["항목","내용"],"rows":[["변제의 제공","변제는 채무내용에 좇은 현실제공으로 한다"],["구두제공","채권자가 미리 수령을 거절하거나 채권자의 행위가 필요하면 변제준비 완료를 통지하고 수령을 최고하는 구두제공으로 충분하다(제460조)"],["변제제공의 효과","그때부터 채무불이행 책임을 면한다(제461조)"],["일부 제공","1억 원 중 7천만 원만 공탁한 것처럼 일부 제공은 채권자가 수락하지 않으면 효력이 없다"],["특정물","이행기의 현상대로 인도한다(제462조)"],["변제 장소","장소를 정하지 않으면 특정물 인도는 채권 성립 당시 그 물건이 있던 장소, 그 밖의 채무는 채권자의 현주소에서 한다(제467조)"],["변제기 전 변제","변제기 전에도 상대방의 손해를 배상하고 변제할 수 있으며(제468조), 변제기 전에 변제한 채무자는 반환을 청구하지 못한다"],["채권의 준점유자","변제자가 선의·무과실일 때 효력이 있다(제470조)"],["영수증 소지자","변제자가 권한 없음을 알았거나 알 수 있었으면 효력이 없다(제471조)"],["그 밖의 무권한자","채권자가 이익을 받은 한도에서 효력이 있다(제472조)"],["채무 없음을 알고 임의로 변제하면","반환을 청구하지 못한다"]]},{"t":"table","title":"변제충당과 변제자대위","head":["항목","내용"],"rows":[["충당의 순서","합의 충당이 가장 우선하고, 다음으로 변제자가 지정하며 변제자가 지정하지 않으면 변제받는 자가 지정한다(제476조)"],["법정충당","이행기가 도래한 채무, 변제이익이 많은 채무, 이행기가 먼저 도래한 채무 순이고 모두 같으면 채무액에 비례한다(제477조)"],["비용·이자·원본","순서로 충당하며 채무자가 원본 먼저 충당을 지정할 수 없다(제479조)"],["주채무자","보증인 유무가 변제이익에 차이를 주지 않으므로 이율이 높은 채무가 변제이익이 크다"],["변제할 정당한 이익이 있는 자","당연히 채권자를 대위하고(제481조), 그 밖의 자는 채권자의 승낙을 얻어 대위한다(제480조)"],["보증인","대위 부기등기 없이도 후순위 근저당권자에게 대위할 수 있다"],["물상보증인","물상보증인 상호간은 재산 가액에 비례해 대위하고, 물상보증인은 제3취득자에게 전부 대위하지만 제3취득자는 물상보증인에게 대위하지 못한다"],["일부대위자","변제한 가액에 비례해 채권자와 함께 권리를 행사하고 저당권을 준공유하며 채권자는 저당권 일부이전 부기등기를 해 줄 의무가 있다"],["배당","채권자가 일부대위자보다 우선한다"],["해제·해지","채무불이행을 이유로 한 해제·해지는 채권자만 할 수 있다(제483조)"],["여러 사람이 시기를 달리해 일부씩 대위변제하면","시기와 관계없이 변제금액에 비례해 배당받는다"]]},{"t":"table","title":"상계","head":["항목","내용"],"rows":[["요건","같은 종류의 채무가 서로 대립하고 자동채권의 변제기가 도래해야 한다"],["수동채권","기한의 이익을 포기할 수 있으므로 변제기 전이라도 상계할 수 있고, 이행지가 달라도 상계할 수 있다"],["동시이행항변권이 붙은 채권","자동채권으로 쓰지 못한다"],["시효 완성 전에 상계적상에 있었던 채권","완성 후에도 상계할 수 있고(제495조), 확정된 벌금채권도 자동채권이 된다"],["고의의 불법행위","채무자는 그 채무를 수동채권으로 상계하지 못하지만 중과실 불법행위는 금지 대상이 아니며, 피해자는 손해배상채권으로 상계할 수 있다(제496조)"],["압류금지채권","임금채권 등을 수동채권으로 하는 상계도 금지된다(제497조)"],["지급금지명령을 받은 제3채무자","그 후 취득한 채권으로 상계하지 못하나, 압류 전에 취득했고 변제기가 먼저 오는 채권으로는 상계할 수 있다(제498조)"],["상계의 방법","조건·기한을 붙이지 못하고 상계적상 시로 소급해 소멸한다(제493조)"]]},{"t":"table","title":"공탁·경개·준소비대차","head":["항목","내용"],"rows":[["변제공탁","채권자의 수익 의사표시와 관계없이 공탁공무원의 수탁처분과 공탁물보관자의 수령으로 효력이 생긴다"],["경개","채무의 중요한 부분을 변경하면 경개로 구채무가 소멸한다(제500조)"],["준소비대차","기존 채무를 소비대차 목적으로 하기로 약정하고 의사가 분명하지 않으면 경개가 아니라 준소비대차로 본다"],["부진정연대채무자 1인의 상계나 상계계약","다른 채무자에게도 효력이 있다"]]}],"13":[{"t":"table","title":"청약·승낙·계약체결상의 과실","head":["항목","내용"],"rows":[["청약","구체적·확정적이어야 하지만 상대방이 특정될 필요는 없다"],["청약의 철회","민법은 청약을 철회하지 못한다고만 정하고 철회 예외를 두지 않는다(제527조)"],["승낙기간을 정하지 않은 청약","상당한 기간 내에 승낙 통지를 받지 못하면 효력을 잃는다(제529조)"],["발송 후 도달 전 청약자가 사망","청약의 효력에는 영향이 없다"],["분양광고","청약의 유인이면 피유인자의 청약에 분양자가 승낙해야 계약이 성립한다"],["격지자간 계약","승낙 통지를 발송한 때 성립한다(제531조)"],["연착된 승낙","계약을 성립시키지 않고 청약자가 새 청약으로 볼 수 있다(제530조)"],["교차청약","양 청약이 모두 도달한 때(제533조)"],["의사실현","승낙으로 인정되는 사실이 있는 때 성립한다(제532조)"],["조건을 붙이거나 변경을 가한 승낙","청약 거절과 새 청약으로 본다(제534조)"],["계약체결상의 과실","원시적·객관적 전부불능인 계약에서 불능을 알았거나 알 수 있었던 자는 선의·무과실의 상대방이 받은 신뢰손해를 배상하되 이행이익을 넘지 못한다(제535조)"],["타인 물건의 매매","원시적 불능이 아니어서 유효하다"],["제535조 책임을 묻지 못하는 경우","수량지정 매매의 면적 부족이나 의사 불합치로 계약이 불성립한 경우"],["계약교섭의 부당파기","불법행위가 된다"]]},{"t":"table","title":"동시이행의 항변권","head":["항목","내용"],"rows":[["동시이행 관계","상대방의 이행제공이 있을 때까지 항변권을 행사하지 않아도 이행지체 책임을 지지 않는다"],["선이행의무자","상대방의 이행이 곤란할 현저한 사유가 있으면 이행을 거절할 수 있다(제536조 제2항)"],["한 채무가 손해배상채무로 바뀌어도","동시이행 관계가 유지된다"],["중도금을 지체한 채 잔금기일이 지나면","중도금·지연손해금·잔금과 소유권이전의무가 동시이행이 되어 중도금 지연손해금은 잔금기일 이후 생기지 않는다"],["동시이행인 것","취소·해제 후 쌍방의 원상회복의무, 임대차 종료 시 목적물반환과 보증금반환, 건물매수청구 후 건물 인도·등기와 대금 지급, 하자보수에 갈음한 손해배상과 보수 지급, 해제 시 가등기말소와 대금반환"],["채권증서 반환과 변제","동시이행이 아니고 영수증 교부와 변제가 동시이행이다"],["동시이행이 아닌 것","무효인 경매의 매수인 등기말소의무와 근저당권자의 배당금 반환의무도 동시이행이 아니다"]]},{"t":"table","title":"위험부담과 제3자를 위한 계약","head":["항목","내용"],"rows":[["위험부담","쌍방 책임 없는 사유로 불능이 되면 채무자는 상대방의 이행을 청구하지 못한다(제537조)"],["채권자 책임 있는 사유나 채권자 수령지체","중 쌍방 책임 없는 사유로 불능이 되면 채무자는 반대급부를 청구할 수 있고, 자기 채무를 면해 얻은 이익은 상환해야 한다(제538조)"],["원시적 불능","계약 당시 이미 멸실된 원시적 불능에는 위험부담이 문제되지 않고, 지급한 대금은 부당이득으로 반환을 청구한다"],["수익자","계약 당시 특정·현존하지 않아도 되고, 낙약자에게 수익의 의사표시를 한 때 권리를 취득한다(제539조)"],["권리가 생긴 후 당사자","이를 변경·소멸시키지 못하지만 미리 유보했으면 할 수 있다(제541조)"],["요약자","낙약자에게 제3자에게 이행하라고 요구할 수 있고, 수익자 동의 없이 해제할 수 있으며 수익자에게는 해제권이 없다"],["낙약자","기본관계의 항변으로는 대항하지만 대가관계의 항변으로는 대항하지 못하고, 해제 후 수익자에게 이미 지급한 것의 반환을 청구하지 못한다"],["제3자를 위한 계약","채무면제 약정과 병존적 채무인수도 제3자를 위한 계약이다"]]},{"t":"table","title":"해제","head":["항목","내용"],"rows":[["이행지체","상당한 기간을 정해 최고한 뒤 해제하고, 미리 이행거절 의사를 표시하면 최고와 자기 채무의 이행제공이 필요 없다(제544조)"],["이행불능","최고 없이 해제한다(제546조)"],["부수의무 위반","원칙적으로 해제권을 발생시키지 않는다"],["과다최고","그 금액이 아니면 수령하지 않을 것이 분명하면 그 최고에 기한 해제는 무효다"],["실권특약","중도금 미지급 시 최고 없이 해제된다는 실권특약은 효력이 있지만 잔금에 관한 실권특약은 매도인이 이행을 제공해야 해제된다"],["해제의 철회","해제는 철회하지 못하고(제543조)"],["당사자가 여럿","전원으로부터 또는 전원에 대해 해야 하며 1인의 해제권이 소멸하면 전원에 대해 소멸한다(제547조)"],["반환할 금전","받은 날부터 이자를 붙이지만(제548조 제2항) 합의해제에는 이 규정이 적용되지 않는다"],["손해배상","해제는 손해배상청구에 영향이 없고(제551조) 이행이익 배상이 원칙이나, 약정해제권 행사에는 손해배상이 따르지 않는다"],["원상회복","과실상계가 적용되지 않는다"],["보호받는 제3자","해제 전에 등기·압류 등으로 완전한 권리를 얻은 자이고, 계약상 채권 자체의 양수인·압류자는 포함되지 않으며 해제 후 이해관계인은 선의여야 한다"],["해제권의 소멸","해제권자의 가공·개조로 목적물이 다른 종류가 되면 해제권은 소멸한다(제553조)"]]}],"14":[{"t":"table","title":"증여와 매매","head":["항목","내용"],"rows":[["증여의 해제 사유","서면에 의하지 않은 증여, 수증자의 범죄행위·부양의무 불이행, 증여자의 재산상태 현저한 변경은 해제 사유이지만 이미 이행한 부분에는 영향이 없다(제555조~제558조)"],["증여자의 담보책임","하자를 알고 고지하지 않은 경우가 아니면 지지 않는다"],["부담부 증여","부담의 한도에서 매도인과 같은 담보책임을 진다(제559조)"],["부담 불이행으로 해제하면","이행된 부분도 원상회복하고, 부담의 존재는 주장하는 자가 증명한다"],["일방예약","상대방이 완결 의사를 표시하는 때 매매의 효력이 생긴다(제564조)"],["매매비용","쌍방이 균분한다(제566조)"],["인도하지 않은 목적물의 과실","매도인에게 속하지만 매수인이 대금을 완제하면 인도 전이라도 과실은 매수인에게 속한다"],["인도받은 매수인","대금 완납 전이라도 사용이익을 부당이득으로 반환하지 않는다"],["환매","환매기간은 부동산 5년, 동산 3년을 넘지 못하고 매매등기와 동시에 환매 보류를 등기해야 제3자에게 효력이 있다(제591조·제592조)"]]},{"t":"table","title":"계약금과 담보책임","head":["항목","내용"],"rows":[["계약금","다른 약정이 없으면 해약금으로 추정되고 위약금 약정이 없으면 채무불이행 해제 시 당연히 몰수되지 않는다"],["해약금 해제","일방이 이행에 착수할 때까지 교부자는 포기, 수령자는 배액 상환으로 해제할 수 있다(제565조)"],["이행 착수","중도금을 지급하면 이행 착수이고, 이행 최고나 대금 청구 소송만으로는 착수가 아니다"],["배액","이행제공하면 족하고 공탁할 필요는 없다"],["계약금 일부만 받았으면","약정 계약금의 배액을 상환해야 하고, 해약권 배제 약정이 있으면 해약금 해제를 할 수 없다"],["해약금 해제의 효과","손해배상이 없다"],["전부 타인 권리","악의 매수인도 해제할 수 있으나 손해배상은 선의만 청구한다(제570조)"],["수량지정 매매의 수량 부족","선의 매수인이 대금감액 등을 청구한다(제574조)"],["제한물권·유치권으로 목적을 달성할 수 없으면","선의 매수인이 해제하고(제575조)"],["저당권·전세권 실행으로 소유권을 잃으면","악의여도 해제할 수 있다(제576조)"],["하자담보","매수인이 선의·무과실이어야 하고 경매에는 적용되지 않으며(제580조), 안 날부터 6월 내 행사한다(제582조)"],["담보책임이 성립해도","착오 취소는 따로 할 수 있다"]]},{"t":"table","title":"소비대차·사용대차·임대차","head":["항목","내용"],"rows":[["소비대차","반환시기 약정이 없는 소비대차는 상당한 기간을 정해 최고해야 지체가 된다"],["사용대차","무상계약이고, 차주는 통상의 필요비를 부담하며 대주 승낙 없이 제3자에게 사용하게 하면 대주가 해지할 수 있다(제610조)"],["공동차주","연대하여 의무를 진다(제616조)"],["임대차의 효력","임대할 권한이 없어도 임대차는 유효하고 영구 임대차도 가능하며 처분권한 없는 자의 건물 임대차는 3년을 넘지 못한다(제619조)"],["임대차등기","등기한 때부터 제3자에게 효력이 있다(제621조)"],["수선의무","사소한 파손은 수선의무가 없고, 수선으로 사용에 지장이 생기면 그 한도에서 차임을 거절할 수 있다"],["상환","필요비는 즉시, 유익비는 종료 시 가액 증가가 현존할 때 상환받는다(제626조)"],["기간 약정이 없으면","임대인의 해지통고는 6월, 임차인은 1월 후 효력이 생긴다(제635조)"],["차임 연체","건물 차임 연체액이 2기분에 이르면 해지할 수 있다(제640조)"],["무단 양도·전대","해지 사유다(제629조)"],["연체차임","임대차 종료 후 목적물 반환 시 보증금에서 당연히 공제된다"],["임대인 귀책으로 해지돼도","임차인은 원상회복의무를 진다"],["원인불명 화재로 멸실되면","임차인이 선관주의를 다했음을 증명해야 면책된다"],["건물 임차인","동의 받은 부속물의 매수를 청구할 수 있으나 토지 임차인에게는 부속물매수청구권이 없다(제646조)"],["토지 임차인의 지상물매수청구권","해지통고로 소멸한 경우에도 인정되고, 미등기 무허가 건물이나 저당권 설정 건물도 대상이며 철거 특약은 무효다(제643조·제652조)"],["차임 연체 등 임차인의 채무불이행으로 해지되면","인정되지 않는다"],["묵시적 갱신 시","제3자가 제공한 담보는 소멸한다"]]},{"t":"table","title":"고용·도급·여행·위임·조합·화해","head":["항목","내용"],"rows":[["보수","보수 관행이 있으면 명시적 합의가 없어도 보수를 청구할 수 있다"],["전적","근로자 동의가 필요하다"],["해지의 부득이한 사유","의무의 중대한 위반도 해지의 부득이한 사유다(제661조)"],["수급인","이행대행자를 쓸 수 있고, 하자보수에 갈음한 손해배상과 동시이행으로 거절할 수 있는 보수는 그 배상액 상당액에 한하며 그 배상액은 청구 시 기준이다"],["저당권설정청구권","공사대금채권과 함께 이전한다"],["도급인","완성 전 손해를 배상하고 해제할 수 있으며 이때 과실상계를 주장하지 못한다(제673조)"],["여행자","개시 전 언제든 해제하되 손해를 배상하고(제674조의3)"],["시정","시정에 지나치게 많은 비용이 들면 시정을 청구하지 못하며 담보책임은 종료일부터 6개월 내 행사하고 여행자에게 불리한 약정만 무효다"],["수임인","무상이어도 선관주의의무를 지고(제681조), 승낙이나 부득이한 사유가 있어야 복위임하며 비용 선급을 청구할 수 있다(제687조)"],["보수 약정","특약이 있어야 청구하지만 변호사에게는 묵시적 보수 약정이 인정된다"],["해지","각 당사자는 언제든 해지할 수 있고, 부득이한 사유 없이 불리한 시기에 해지한 때만 손해를 배상한다(제689조)"],["위임 종료","사망·파산·수임인의 성년후견개시로 위임이 종료한다(제690조)"],["조합","출자는 노무로도 할 수 있고 조합계약은 해제할 수 없으며 조합원 1인을 채무자로 한 가압류로 조합재산을 집행하지 못한다"],["화해","착오로 취소하지 못하지만 당사자 자격이나 분쟁 이외의 사항에 관한 착오는 예외이고(제733조), 사기로 인한 화해는 취소할 수 있다"]]}],"15":[{"t":"table","title":"사무관리","head":["항목","내용"],"rows":[["성립","의무 없이 타인을 위해 사무를 관리해야 한다"],["타인을 위한 의사","외부에 표시될 필요가 없고 자기 이익을 위한 의사와 함께 있어도 된다"],["성립하지 않는 경우","제3자와의 약정에 따라 처리한 사무는 원칙적으로 그 타인과의 관계에서 사무관리가 아니고, 본인의 의사에 반함이 명백하면 성립하지 않는다"],["관리 방법","관리자는 본인에게 가장 이익되는 방법, 본인의 의사를 알 수 있으면 그 의사에 맞게 관리한다(제734조)"],["긴급사무관리","급박한 위해를 면하게 하려는 긴급사무관리는 고의나 중대한 과실이 없으면 손해배상책임이 없다(제735조)"],["비용 상환","필요비·유익비 상환을 청구할 수 있고, 본인 의사에 반해 관리했으면 현존이익 한도로 줄어든다(제739조)"],["제3자가 이익을 얻어도","관리자는 그 제3자에게 직접 부당이득반환을 청구하지 못한다"]]},{"t":"table","title":"부당이득의 요건","head":["항목","내용"],"rows":[["요건","법률상 원인 없이 타인의 재산이나 노무로 이익을 얻고 그로 인해 타인에게 손해를 가해야 한다(제741조)"],["채권 취득","이득이다"],["손실자가 없으면","이득자는 있어도 성립하지 않는다"],["수익자의 고의·과실","요건이 아니다"],["권원 없이 타인 건물에 거주하면","차임 상당액을 반환한다"],["임대차 종료 후 동시이행항변으로 점유해도","실제 사용이익을 반환한다"],["급부부당이득","법률상 원인이 없다는 점을 반환을 청구하는 사람이 증명한다"],["계약상 급부가 제3자에게 이익이 되었어도","급부자는 계약 상대방에게만 청구하고 제3자에게 직접 청구하지 못한다"],["해제 시 반환 금전에 붙이는 이자","지연손해금이 아니라 부당이득반환의 성질이다"]]},{"t":"table","title":"비채변제와 불법원인급여","head":["항목","내용"],"rows":[["채무 없음을 알고 변제하면","반환을 청구하지 못하며(제742조), 몰랐다면 과실이 있어도 이 조항이 적용되지 않는다"],["착오로 한 비채변제","도의관념에 맞으면 반환을 청구하지 못한다(제744조)"],["기한 전 변제","반환을 청구하지 못하지만 착오로 변제했으면 채권자는 얻은 이익을 반환한다(제743조)"],["불법원인급여","불법의 원인으로 급여한 것은 반환을 청구하지 못하지만 불법원인이 수익자에게만 있으면 청구할 수 있다(제746조)"],["불법성","수익자의 불법성이 현저히 크고 급여자의 불법성이 경미하면 반환청구가 허용된다"],["반환이 금지되는 이익","종국적인 것이어야 한다"]]},{"t":"table","title":"반환범위","head":["항목","내용"],"rows":[["선의 수익자","현존이익"],["악의 수익자","받은 이익에 이자를 붙이고 손해를 배상한다(제748조)"],["금전 이득","소비 여부와 관계없이 현존하는 것으로 추정한다"],["악의가 되는 때","이익을 받은 뒤 원인 없음을 알면 그때부터 악의이고, 선의 수익자가 패소하면 소를 제기한 때부터 악의로 본다(제749조)"],["원물을 처분해 반환할 수 없으면","처분 당시의 대가를 반환한다"],["제한능력자","악의라도 현존이익만 반환한다"]]}],"16":[{"t":"table","title":"일반불법행위와 책임능력","head":["항목","내용"],"rows":[["일반불법행위","고의 또는 과실로 인한 위법행위로 타인에게 손해를 가한 자가 배상한다(제750조)"],["부작위 불법행위","법적 작위의무가 객관적으로 인정되면 의무자가 그 존재를 몰랐어도 성립한다"],["재산권 침해","재산적 손해 배상으로 정신적 고통도 회복된다고 보는 것이 원칙이다"],["태아","손해배상청구권에 관해 이미 출생한 것으로 보지만(제762조) 모체 안에서 사망한 태아는 청구권이 없다"],["책임능력 없는 자의 감독의무자","감독의무를 게을리하지 않았음을 스스로 증명해야 면책된다(제755조)"],["책임능력 있는 미성년자의 감독의무자","의무위반과 손해 사이에 상당인과관계가 있으면 일반불법행위책임을 진다"]]},{"t":"table","title":"사용자책임","head":["항목","내용"],"rows":[["사용자책임의 요건","실질적인 지휘·감독 관계가 필요하고, 외형상 사무집행으로 보이면 행위자의 주관적 사정과 관계없이 사무집행에 관한 행위다"],["피해자가 직무 범위가 아님을 알았거나 중과실로 몰랐으면","책임이 없다"],["도급인","원칙적으로 책임이 없지만(제757조) 수급인의 일을 구체적으로 지휘·감독했으면 사용자책임을 진다"],["파견사업주","선발·일반적 지휘감독에 주의를 다하지 않았으면 책임을 진다"],["퇴직 후 행위","대상이 아니다"],["사용자의 책임 범위","피용자와 같은 범위의 책임을 지므로 공동불법행위자들의 과실비율과 관계없이 피용자가 질 전액을 배상한다"],["피용자의 고의 영득행위","사용자는 피해자의 과실을 들어 감경을 주장할 수 있다"],["구상권","사용자의 피용자에 대한 구상권은 신의칙상 제한될 수 있다"]]},{"t":"table","title":"공작물책임과 공동불법행위","head":["항목","내용"],"rows":[["공작물 하자","설치·보존의 하자로 인한 손해는 1차로 점유자가 배상하고, 점유자가 필요한 주의를 다했으면 소유자가 배상한다(제758조)"],["소유자 책임","무과실책임이다"],["손해의 요건","공작물 하자와 관련된 위험이 현실화되어 생긴 손해여야 한다"],["공동불법행위자","연대하여 배상하고 교사자·방조자도 공동행위자로 본다(제760조)"],["방조","과실에 의한 방조, 작위의무자의 부작위에 의한 방조도 성립하지만 방조와 손해 사이에 상당인과관계가 있어야 한다"],["부진정연대채무","관계는 부진정연대채무여서 1인에 대한 이행청구는 다른 자의 시효를 중단시키지 않는다"],["과실상계","피해자의 과실을 전원에 대해 전체적으로 평가하고, 고의로 피해자 부주의를 이용한 자가 있어도 그렇지 않은 자는 과실상계를 주장할 수 있다"],["금액이 다른 부진정연대채무","다액채무자의 일부 변제는 단독 부담 부분부터 소멸한다"]]},{"t":"table","title":"손해배상의 내용과 소멸시효","head":["항목","내용"],"rows":[["위자료","신체·자유·명예 침해에는 위자료를 배상하고, 생명침해 시 직계존속·직계비속·배우자는 재산상 손해가 없어도 위자료를 청구한다(제751조·제752조)"],["지체","불법행위 손해배상채무는 최고 없이 성립과 동시에 지체가 되고, 고의의 불법행위자는 그 채무를 수동채권으로 상계하지 못한다(제496조)"],["배상액 경감","고의·중과실이 아니고 생계에 중대한 영향이 있으면 배상액 경감을 청구할 수 있다(제765조)"],["소멸시효","손해 및 가해자를 안 날부터 3년, 불법행위를 한 날부터 10년이다(제766조)"],["미성년자","성폭력·성추행 등 성적 침해를 당하면 성년이 될 때까지 시효가 진행하지 않는다"],["시효 항변","채무불이행 손해배상청구권에 대한 시효 항변에 불법행위 청구권의 시효 항변이 포함되지 않는다"]]}]};
