(window.TNQ=window.TNQ||[]).push({"terms":{"관습법":{"d":"되풀이된 관행에 법적 확신이 더해져 법규범으로 인정된 불문법입니다.","r":[]},"신의칙":{"d":"권리를 행사하고 의무를 이행할 때 상대방의 신뢰를 저버리지 않아야 한다는 원칙입니다.","r":[]},"사인증여":{"d":"증여자가 사망하면 효력이 생기는 증여로 계약이라서 수증자의 수령 능력이 필요합니다.","r":[]},"비법인사단":{"d":"법인격은 없으나 사단의 실체를 갖춘 단체로 구성원의 총유로 재산을 가집니다.","r":[]},"명인방법":{"d":"수목의 소유권을 제3자가 알 수 있도록 껍질을 벗겨 표시하는 등 관습법상 공시방법입니다.","r":[]},"종물":{"d":"주물의 상용에 이바지하는 독립한 물건으로 주물의 처분에 따라 함께 처분됩니다.","r":["주물"]},"주물":{"d":"종물이 도움을 주는 중심 물건으로 종물과 함께 처분되는 기준이 됩니다.","r":["종물"]},"제사주재자":{"d":"조상의 제사를 주재하며 유체와 분묘 등을 귀속받는 사람입니다.","r":[]},"통정허위표시":{"d":"상대방과 짜고 진의 없이 하는 의사표시로 무효이지만 선의 제3자에게는 대항하지 못합니다.","r":["비진의표시"]},"비진의표시":{"d":"표의자가 진의 아님을 알면서 하는 의사표시로 원칙적으로 유효합니다.","r":["통정허위표시"]},"복대리":{"d":"대리인이 자기 이름으로 선임한 대리인이 본인을 대리하는 것입니다.","r":[]},"제척기간":{"d":"권리의 존속기간으로 중단이 없고 법원이 직권으로 조사합니다.","r":["소멸시효"]},"소멸시효":{"d":"권리를 행사하지 않은 상태가 일정 기간 이어지면 권리가 소멸하는 제도입니다.","r":["제척기간"]},"분묘기지권":{"d":"남의 땅에 분묘를 설치한 사람이 그 기지를 사용할 수 있는 관습법상 물권입니다.","r":[]},"법정지상권":{"d":"토지와 건물의 소유자가 달라질 때 법률 규정으로 건물 소유자에게 생기는 지상권입니다.","r":[]},"점유개정":{"d":"양도인이 목적물을 계속 점유하면서 양수인을 위해 점유하겠다고 약정하는 인도 방법입니다.","r":[]},"혼동":{"d":"소유권과 제한물권 같은 물권이 한 사람에게 귀속해 제한물권이 소멸하는 것입니다.","r":[]},"요역지":{"d":"지역권에서 편익을 받는 토지입니다.","r":[]},"유치권":{"d":"남의 물건을 점유한 사람이 그 물건에 관해 생긴 채권을 변제받을 때까지 유치하는 법정담보물권입니다.","r":[]},"물상대위":{"d":"담보물이 없어지고 대신 생긴 금전 등에 담보물권의 효력을 미치게 하는 것입니다.","r":[]},"전질":{"d":"질권자가 자기 책임으로 질물을 다시 질권의 목적으로 삼는 것입니다.","r":[]},"근저당":{"d":"채권 최고액만 정하고 실제 채무는 장래에 확정하는 저당권입니다.","r":[]},"이행보조자":{"d":"채무자가 채무를 이행하는 데 사용하는 사람으로 그의 고의·과실은 채무자의 것으로 봅니다.","r":[]},"과실상계":{"d":"손해 발생에 채권자의 과실이 있으면 배상액을 줄이는 제도입니다.","r":["손익상계"]},"손익상계":{"d":"손해를 입으면서 같은 원인으로 이익을 얻었을 때 그 이익을 배상액에서 빼는 것입니다.","r":["과실상계"]},"채권자지체":{"d":"채권자가 이행 제공을 받고도 수령하지 않거나 협력하지 않아 생기는 지체입니다.","r":[]},"채권자대위권":{"d":"채권자가 자기 채권을 보전하려고 채무자의 권리를 대신 행사하는 권리입니다.","r":["채권자취소권"]},"채권자취소권":{"d":"채무자가 채권자를 해하는 재산행위를 했을 때 채권자가 법원에 취소를 구하는 권리입니다.","r":["채권자대위권","수익자"]},"수익자":{"d":"채권자취소권에서 사해행위로 이익을 받은 사람입니다.","r":["전득자"]},"전득자":{"d":"수익자로부터 목적물을 다시 취득한 사람입니다.","r":["수익자"]},"부진정연대채무":{"d":"여러 채무자가 같은 내용의 채무를 지지만 주관적 공동관계가 없어 절대적 효력이 제한되는 채무입니다.","r":["불가분채무"]},"불가분채무":{"d":"급부의 성질상 나눌 수 없는 채무로 여러 채무자가 연대와 비슷하게 책임을 집니다.","r":[]},"면책적 인수":{"d":"인수인이 채무를 넘겨받아 전 채무자가 채무에서 벗어나는 채무인수입니다.","r":["병존적 인수"]},"병존적 인수":{"d":"인수인이 채무를 부담하면서 전 채무자의 채무도 그대로 남는 채무인수입니다.","r":["면책적 인수"]},"이행인수":{"d":"인수인이 채권자에 대해 채무를 지지 않고 채무자에 대해서만 이행할 의무를 지는 약정입니다.","r":[]},"물상보증인":{"d":"남의 채무를 위해 자기 재산을 담보로 제공한 사람입니다.","r":[]},"상계적상":{"d":"상계를 할 수 있도록 두 채권이 대립하고 변제기에 이른 상태입니다.","r":["자동채권","수동채권"]},"자동채권":{"d":"상계하는 사람이 가진 채권으로 상계의 의사표시로 소멸시키는 채권입니다.","r":["수동채권"]},"수동채권":{"d":"상계를 당하는 상대방이 가진 채권으로 상계하는 사람이 부담하는 채무입니다.","r":["자동채권"]},"경개":{"d":"기존 채무를 소멸시키고 새 채무를 성립시키는 계약입니다.","r":["준소비대차"]},"준소비대차":{"d":"기존 채무를 소비대차의 목적으로 하기로 약정하는 계약입니다.","r":["경개"]},"동시이행":{"d":"쌍무계약에서 한쪽이 이행을 제공하지 않는 한 상대방도 자기 채무의 이행을 거절할 수 있는 관계입니다.","r":[]},"위험부담":{"d":"쌍방의 책임 없는 사유로 급부가 불능이 되었을 때 그 불이익을 누가 지는지를 정하는 제도입니다.","r":[]},"낙약자":{"d":"제3자를 위한 계약에서 제3자에게 급부를 약속한 사람입니다.","r":[]},"실권특약":{"d":"채무 불이행 시 최고 없이 계약이 당연히 해제되거나 권리가 소멸한다는 특약입니다.","r":[]},"환매":{"d":"매도인이 대금과 매매비용을 반환하고 목적물을 되사는 권리입니다.","r":[]},"부속물매수청구권":{"d":"건물 임차인이 임대인 동의를 받아 설치한 부속물의 매수를 임대인에게 청구하는 권리입니다.","r":[]},"사무관리":{"d":"법적 의무 없이 타인을 위해 그 사무를 처리하는 행위입니다.","r":[]},"사용자책임":{"d":"피용자가 사무집행 중 가한 불법행위에 대해 사용자가 지는 배상책임입니다.","r":[]},"공동불법행위":{"d":"여러 사람이 함께 불법행위를 하여 연대하여 배상책임을 지는 경우입니다.","r":["부진정연대채무"]}},"notes":{"(채무면제 승낙)는 단독으로 확정 유효이고, 처분 허락은 묵시적으로도 가능하다":"미성년자가 이익만 얻는 행위는 단독으로 확정 유효하고 재산 처분 허락은 묵시적으로도 할 수 있습니다.","10년, 선의·무과실로 개시하면 5년이다(제246조)":"동산은 10년 점유로 취득하고 선의·무과실로 시작하면 5년이면 됩니다.","10년을 넘지 못하고 건물 전세권을 1년 미만으로 정하면 1년으로 한다(제312조)":"전세권 존속기간은 10년을 넘지 못하고 건물 전세권을 1년 미만으로 정하면 1년으로 봅니다.","19세로 성년이 되고 출생일을 산입하므로 2018.12.1. 출생자는 2037.12.1. 0시에 성년이다":"성년 판단은 출생일을 첫날에 넣어 계산하므로 2018.12.1.생은 2037.12.1. 0시부터 성년입니다.","1개월 이상의 기간을 정해 한다(제15조)":"확답촉구는 1개월 이상의 기간을 정해 추인 여부를 묻는 방식으로 합니다.","1억 원 중 7천만 원만 공탁한 것처럼 일부 제공은 채권자가 수락하지 않으면 효력이 없다":"일부만 공탁하는 것처럼 채무 일부만 제공하면 채권자가 받아들이지 않는 한 변제 제공으로 인정되지 않습니다.","20년간 소유의 의사로 평온·공연하게 점유하고 등기해야 소유권을 취득한다":"부동산 취득시효는 20년간 소유의 의사로 평온·공연하게 점유하고 등기해야 소유권을 얻습니다.","5년 내로만 할 수 있다(제268조)":"공유물 분할금지 약정은 5년을 넘지 않는 기간으로만 할 수 있습니다.","60세에 도달하는 날을 말한다":"정년 60세는 60세가 되는 날을 가리킵니다.","가압류권자, 파산관재인(채권자 일부라도 선의면 선의), 악의자로부터의 선의 전득자가 포함된다":"허위표시를 기초로 새 이해관계를 맺은 가압류권자, 파산관재인, 선의 전득자는 보호 대상인 제삼자입니다.","가압류 집행이나 강제경매 진행 중이라는 사정만으로도 불능이 아니며, 증여 대상 권리가 타인에게 있다는 것만으로도 불능이 아니다":"가압류나 강제경매 진행, 증여 대상 권리가 타인에게 있다는 사정만으로는 이행불능이 아닙니다.","가족관계등록부가 아니라 후견등기부에 공시한다":"후견은 가족관계등록부가 아닌 후견등기부로 공시합니다.","각 당사자는 언제든 해지할 수 있고, 부득이한 사유 없이 불리한 시기에 해지한 때만 손해를 배상한다(제689조)":"위임은 각 당사자가 언제든 해지할 수 있고 부득이한 사유 없이 불리한 때 해지한 경우에만 배상합니다.","각자대리가 원칙이다(제119조)":"대리인이 여럿이면 각자가 단독으로 대리하는 것이 원칙입니다.","감독의무를 게을리하지 않았음을 스스로 증명해야 면책된다(제755조)":"책임능력 없는 자의 감독의무자는 감독을 게을리하지 않았음을 스스로 증명해야 면책됩니다.","감액할 수 없고 공서양속 위반 범위에서만 무효다":"위약벌은 손해배상 예정이 아니라 감액할 수 없고 공서양속 위반 범위에서만 무효입니다.","강제집행을 피하려는 허위 근저당권 설정":"강제집행을 피하려는 허위 근저당 설정은 반사회질서가 아니라 통정허위표시 문제입니다.","같은 물건에 대한 소유권과 다른 물권이 한 사람에게 귀속하면 다른 물권은 소멸한다":"혼동은 같은 물건의 소유권과 제한물권이 한 사람에게 모이면 제한물권이 사라지는 것입니다.","같은 종류의 채무가 서로 대립하고 자동채권의 변제기가 도래해야 한다":"상계는 같은 종류의 채무가 서로 맞서고 자동채권의 변제기가 도래해야 할 수 있습니다.","같은 채권을 위해 여러 부동산에 저당권을 설정하고 동시에 배당하면 각 부동산 경매대가에 비례해 분담한다":"공동저당을 동시에 배당하면 각 부동산의 경매대가에 비례해 채권을 나눠 부담합니다.","개시 전 언제든 해제하되 손해를 배상하고(제674조의3)":"여행자는 여행 개시 전에 언제든 해제할 수 있고 손해를 배상해야 합니다.","객관적 가치로, 판단 시점은 법률행위 당시다":"불균형은 객관적 가치를 기준으로 하며 법률행위 당시를 판단 시점으로 삼습니다.","거듭된 관행이 법적 확신을 얻은 것이다":"관습법은 되풀이된 관행에 사람들의 법적 확신이 더해져 법규범으로 인정된 것입니다.","건물 등이 남아 있으면 지상권자는 갱신을 청구할 수 있고, 설정자가 거절하면 공작물·수목의 매수를 청구할 수 있다(제283조)":"지상권이 끝났을 때 건물이 남으면 갱신을 청구할 수 있고 거절되면 건물·수목 매수를 청구할 수 있습니다.","건물 차임 연체액이 2기분에 이르면 해지할 수 있다(제640조)":"건물 차임 연체액이 2기분에 이르면 임대인이 해지할 수 있습니다.","견고한 건물이나 수목은 30년, 그 밖의 건물은 15년, 건물 외 공작물은 5년보다 짧게 정하지 못한다(제280조)":"지상권은 견고한 건물·수목 30년, 그 밖의 건물 15년, 공작물 5년보다 짧게 정할 수 없습니다.","경과실로 착오한 자가 취소해도 신뢰이익 배상책임은 없고, 제109조 배제 특약은 유효하다":"경과실로 착오한 사람이 취소해도 신뢰이익을 배상하지 않으며 착오 배제 특약은 유효합니다.","경매를 청구할 수 있다(제318조)":"전세금 반환이 지체되면 전세권자는 경매를 청구할 수 있습니다.","경영방침에 따른 사직서 제출 후 즉시 재입사는 비진의표시이고, 희망퇴직 권고를 받고 숙고해 낸 사직서는 아니다":"경영방침에 따른 사직서 제출 뒤 곧바로 재입사하면 비진의표시이나 숙고해 낸 희망퇴직 사직서는 아닙니다.","경제적 불이익이 없으면 중요부분이 아니고, 동기는 법률행위 내용으로 삼았으면 취소 대상이다":"경제적 불이익이 없으면 중요부분이 아니고 동기도 내용으로 삼았다면 취소할 수 있습니다.","계속 관리하더라도 토지에 부합한다":"권원 없이 남의 땅에 심은 수목은 계속 가꿔도 토지에 부합해 토지 소유자 것이 됩니다.","계속되고 표현된 것에 한해 시효취득할 수 있다(제294조)":"지역권은 계속되고 표현된 것에 한해 시효취득할 수 있습니다.","계약금 배액 상환 해제는 되지만 채무불이행 해제나 계약금 부당이득 반환청구는 안 되고, 협력의무는 소로 구할 수 있다":"유동적 무효 상태에서는 계약금 배액 상환 해제는 되지만 채무불이행 해제는 안 되고 협력의무는 소로 구합니다.","계약 당시 이미 멸실된 원시적 불능에는 위험부담이 문제되지 않고, 지급한 대금은 부당이득으로 반환을 청구한다":"계약 당시 이미 멸실된 원시적 불능은 위험부담이 아니라 부당이득 문제로 지급한 대금을 반환받습니다.","계약 당시 제한능력자임을 알았으면 인정되지 않는다(제16조)":"상대방은 계약 당시 제한능력자임을 알았다면 철회권을 행사하지 못합니다.","계약 당시 특정·현존하지 않아도 되고, 낙약자에게 수익의 의사표시를 한 때 권리를 취득한다(제539조)":"수익자는 계약 당시 특정·현존하지 않아도 되고 낙약자에게 수익의 의사표시를 한 때 권리를 얻습니다.","계약을 성립시키지 않고 청약자가 새 청약으로 볼 수 있다(제530조)":"연착된 승낙은 계약을 성립시키지 않고 청약자가 새 청약으로 볼 수 있습니다.","계약 체결 당시가 아니라 채무불이행 당시다":"손해배상 범위의 판단 시점은 계약 체결이 아니라 채무불이행 당시입니다.","고의·과실은 채무자의 것으로 보고(제391조), 호의로 이행한 제3자도 채무자가 용인했으면 이행보조자다":"채무 이행을 돕는 사람의 잘못은 채무자의 잘못으로 보며 호의로 도운 사람도 채무자가 받아들였다면 포함됩니다.","고의 또는 과실로 인한 위법행위로 타인에게 손해를 가한 자가 배상한다(제750조)":"일반불법행위는 고의 또는 과실로 위법하게 타인에게 손해를 입힌 사람이 배상하는 책임입니다.","고의 또는 중대한 과실이 없으면 책임이 없고(제401조), 보관·변제 비용 증가분은 채권자 부담이다(제403조)":"지체 중 채무자는 고의나 중대한 과실이 없으면 책임이 없고 보관·변제 비용 증가분은 채권자가 부담합니다.","고의·중과실이 아니고 생계에 중대한 영향이 있으면 배상액 경감을 청구할 수 있다(제765조)":"가해자가 고의나 중과실 없이 가해했고 배상 때문에 생계가 크게 위태롭다면 배상액을 줄여 달라고 요청할 수 있습니다.","공부상 등록이 아니라 소유자의 의사 등 주관적 사정을 참작해 사회통념으로 정한다":"건물이 몇 개인지는 등록 내용이 아니라 소유자 의사 등을 참작한 사회통념으로 정합니다.","공사대금채권과 함께 이전한다":"저당권설정청구권은 수급인의 공사대금채권과 함께 이전됩니다.","공작물 하자와 관련된 위험이 현실화되어 생긴 손해여야 한다":"공작물책임에서 배상되는 손해는 하자에 따른 위험이 실제로 발현되어 발생한 것에 한정됩니다.","과실상계로 책임을 줄일 수 없고, 강행법규 위반 행위에는 성립하지 않는다":"표현대리가 인정되면 본인의 책임을 과실상계로 감하지 못하고 강행법규를 어긴 행위에는 인정되지 않습니다.","과실상계를 먼저 하고 손익상계를 나중에 한다":"손해배상액은 과실상계를 먼저 하고 손익상계를 나중에 합니다.","과실에 의한 방조, 작위의무자의 부작위에 의한 방조도 성립하지만 방조와 손해 사이에 상당인과관계가 있어야 한다":"부주의로 돕거나 지켜야 할 행동을 하지 않고 돕는 경우도 방조가 되나 손해와 인과관계가 있어야 합니다.","관계는 부진정연대채무여서 1인에 대한 이행청구는 다른 자의 시효를 중단시키지 않는다":"공동불법행위자의 책임은 부진정연대채무여서 한 사람에 대한 이행청구는 다른 사람의 시효를 중단시키지 않습니다.","관리자는 그 제3자에게 직접 부당이득반환을 청구하지 못한다":"사무관리자는 제3자가 이익을 얻어도 그 제3자에게 직접 부당이득반환을 청구하지 못합니다.","관리자는 본인에게 가장 이익되는 방법, 본인의 의사를 알 수 있으면 그 의사에 맞게 관리한다(제734조)":"사무관리자는 본인에게 가장 유리한 방식으로 하되 본인 의사를 알 수 있다면 그에 맞추어 처리합니다.","관리할 수 있는 전기도 동산이다":"전기처럼 관리할 수 있는 자연력도 법률상 동산으로 봅니다.","관습법상 법정지상권과 분묘기지권":"관습법으로 인정된 물권으로는 관습법상 법정지상권과 분묘기지권이 있습니다.","구성원 개인이 총회 결의를 거쳐도 단독으로 제기할 수 없다":"총유재산 보존행위의 소는 구성원 개인이 총회 결의를 거쳐도 혼자서는 제기할 수 없습니다.","구체적·확정적이어야 하지만 상대방이 특정될 필요는 없다":"청약은 내용이 구체적이고 확정적이어야 하며 불특정 다수를 향해 해도 효력이 생깁니다.","국립공원 입장료나 특허권 사용료는 물건의 사용대가가 아니어서 과실이 아니다":"입장료나 특허권 사용료는 물건의 사용대가가 아니어서 법정과실에 해당하지 않습니다.","궁박·경솔·무경험과 급부 간 현저한 불균형이 필요하고, 폭리자가 그 사정을 알고 이용하려는 의사가 있어야 한다":"불공정한 법률행위는 궁박·경솔·무경험과 현저한 불균형이 있고 폭리자가 이를 알고 이용해야 성립합니다.","궁박은 본인, 경솔·무경험은 대리인을 기준으로 하며 현저한 불균형이 있어도 궁박 등은 추정되지 않는다":"궁박은 본인을, 경솔·무경험은 대리인을 기준으로 보며 불균형만으로 궁박 등이 추정되지는 않습니다.","권리를 행사할 수 있는 때부터 진행하며 권리의 존재를 몰랐다는 사실상 장애는 진행을 막지 않는다(제166조)":"시효는 권리를 행사할 수 있는 때부터 진행하고 권리의 존재를 몰랐다는 사정은 진행을 막지 않습니다.","균등한 것으로 추정한다(제262조)":"공유지분은 균등한 것으로 추정합니다.","그 금액이 아니면 수령하지 않을 것이 분명하면 그 최고에 기한 해제는 무효다":"실제 채무보다 지나치게 많은 금액을 요구하고 그 액수가 아니면 받지 않겠다는 최고에 근거한 해제는 효력이 없습니다.","그 나라의 각종 통화로 변제할 수 있고(제377조)":"외국 통화채권은 그 나라의 여러 종류 통화로 변제할 수 있습니다.","그 대가에서 전액을 받을 수 있고 차순위 저당권자는 대위할 수 있다(제368조)":"공동저당 중 일부만 먼저 배당하면 그 대가에서 전액을 받을 수 있고 차순위 저당권자가 대위합니다.","그때부터 채무불이행 책임을 면한다(제461조)":"변제를 제공하면 그때부터 채무불이행 책임에서 벗어납니다.","그 물권이 제3자의 권리의 목적이 된 때에는 소멸하지 않는다(제191조)":"그 물권이 제3자의 권리 목적이면 혼동이 있어도 사라지지 않습니다.","그 밖의 건물 소유 목적으로 본다(제281조)":"공작물의 종류를 정하지 않았다면 그 밖의 건물 소유를 목적으로 한 것으로 봅니다.","그 밖의 사항은 상대적 효력이어서 승인이나 압류로 인한 시효중단은 다른 연대채무자에게 미치지 않는다(제423조)":"절대적 효력 사유가 아닌 승인이나 압류는 연대채무자 한 명에게만 효력이 있어 다른 사람의 시효는 그대로 갑니다.","그 영업에 관한 법정대리인의 대리권은 소멸한다(제8조)":"법정대리인이 미성년자의 영업을 허락하면 그 영업에 대한 대리권이 사라집니다.","그 익일로 만료한다(제161조)":"기간 말일이 토요일이나 공휴일이면 그 다음 날에 만료합니다.","그 전에 상계적상에 있었으면 자동채권으로 상계할 수 있다":"제척기간이 지난 채권이라도 그 전에 상계적상에 있었다면 자동채권으로 상계할 수 있습니다.","그 전에 생긴 이자·지연손해금도 소멸한다":"원금이 시효로 소멸하면 그 전에 생긴 이자와 지연손해금도 함께 사라집니다.","그 차액만큼 다른 채무자도 면책된다":"남은 채무가 부담부분보다 적어지면 그 차액만큼 다른 채무자도 책임을 면합니다.","그 후 취득한 채권으로 상계하지 못하나, 압류 전에 취득했고 변제기가 먼저 오는 채권으로는 상계할 수 있다(제498조)":"지급금지명령을 받은 제삼채무자는 명령 뒤에 취득한 채권으로 상계하지 못하고 압류 전 취득분으로만 상계합니다.","금전도 특정물채권의 목적이 될 수 있다":"돈이라도 특정한 지폐나 주화처럼 개별로 정해지면 특정물채권의 목적이 될 수 있습니다.","금전채권 보전에는 채무자의 무자력이 필요하지만 소유권이전등기청구권 같은 특정채권 보전에는 필요 없다":"금전채권을 보전하려면 채무자의 무자력이 필요하지만 특정채권을 보전할 때는 필요 없습니다.","금전채권이어야 하고 특정물 이전등기청구권은 원칙적으로 피보전채권이 아니다":"채권자취소권의 피보전채권은 금전채권이어야 하며 특정물 이전등기청구권은 원칙적으로 해당하지 않습니다.","급박한 위해를 면하게 하려는 긴급사무관리는 고의나 중대한 과실이 없으면 손해배상책임이 없다(제735조)":"긴급사무관리는 고의나 중대한 과실이 없으면 손해배상책임을 지지 않습니다.","급부자는 계약 상대방에게만 청구하고 제3자에게 직접 청구하지 못한다":"계약상 급부가 제3자에게 이익이 되어도 급부자는 계약 상대방에게만 청구하고 제3자에게 직접 청구하지 못합니다.","기본관계의 항변으로는 대항하지만 대가관계의 항변으로는 대항하지 못하고, 해제 후 수익자에게 이미 지급한 것의 반환을 청구하지 못한다":"낙약자는 기본관계의 항변으로 수익자에게 맞서지만 대가관계의 항변은 못 하며 해제 후 이미 준 것을 돌려받지 못합니다.","기산일에 소급해 효력이 생긴다(제167조)":"시효가 완성되면 그 효력은 기산일까지 거슬러 올라가 생깁니다.","기존 채무를 소비대차 목적으로 하기로 약정하고 의사가 분명하지 않으면 경개가 아니라 준소비대차로 본다":"기존 채무를 빌린 돈으로 바꾸기로 했는데 뜻이 불분명하면 채무가 소멸하는 경개가 아니라 준소비대차로 봅니다.","기한의 이익을 포기할 수 있으므로 변제기 전이라도 상계할 수 있고, 이행지가 달라도 상계할 수 있다":"수동채권은 기한의 이익을 포기할 수 있으므로 변제기 전에도 상계할 수 있고 이행지가 달라도 가능합니다.","낙약자에게 제3자에게 이행하라고 요구할 수 있고, 수익자 동의 없이 해제할 수 있으며 수익자에게는 해제권이 없다":"요약자는 낙약자에게 수익자에게 이행하라고 요구하고 수익자 동의 없이 해제하며 수익자는 해제권이 없습니다.","뇌물의 소극적 은닉을 위한 임치":"뇌물을 숨기려고 맡기는 임치는 숨기는 데 그치므로 반사회질서 위반에 해당하지 않는다고 봅니다.","다른 약정이 없으면 해약금으로 추정되고 위약금 약정이 없으면 채무불이행 해제 시 당연히 몰수되지 않는다":"계약금은 해약금으로 추정되며 위약금 약정이 없으면 채무불이행 해제 때 당연히 몰수되지 않습니다.","다른 정함이 없으면 채무자에게 있고(제380조) 선택은 채권 발생 시로 소급하며 제3자가 선택할 때는 채무자와 채권자에게 의사표시를 한다":"선택채권의 선택권은 다른 정함이 없으면 채무자에게 있고 선택은 채권 발생 때로 거슬러 효력이 있습니다.","다른 채권은 중단되지 않는다":"여러 채권 중 하나를 행사해도 다른 채권의 시효는 중단되지 않습니다.","다른 채무자에게도 효력이 있다":"부진정연대채무자 한 사람이 상계하면 공동의 채무가 그만큼 줄어 다른 채무자에게도 효과가 미칩니다.","다액채무자의 일부 변제는 단독 부담 부분부터 소멸한다":"금액이 다른 부진정연대채무에서 다액채무자의 일부 변제는 단독으로 부담하는 부분부터 소멸시킵니다.","단독으로 취소할 수 있고 재판 외 의사표시로도 취소한다":"제한능력자는 법정대리인 동의 없이 혼자 취소할 수 있고 재판 밖의 의사표시로도 가능합니다.","담보 손상·감소·멸실, 담보제공 의무 불이행":"담보가 손상·감소·멸실되거나 담보제공 의무를 안 지키면 기한이익을 잃는 사유가 됩니다.","당사자가 원용해야 하며 법원이 직권으로 고려하지 않는다":"시효 완성은 당사자가 원용해야 하고 법원이 직권으로 고려하지 않습니다.","당사자의 청구로 법원이 정한다":"지료는 당사자가 정하지 못했을 때 청구에 따라 법원이 정합니다.","당연히 채권자를 대위하고(제481조), 그 밖의 자는 채권자의 승낙을 얻어 대위한다(제480조)":"변제할 정당한 이익이 있는 사람은 당연히 채권자를 대위하고 그 밖의 사람은 채권자의 승낙을 얻어 대위합니다.","대금 완납 전이라도 사용이익을 부당이득으로 반환하지 않는다":"인도받은 매수인은 대금을 다 내기 전이라도 사용이익을 부당이득으로 반환하지 않습니다.","대리인 기준이다(제116조)":"착오·사기·강박이 있었는지는 본인이 아니라 대리인을 기준으로 판단합니다.","대리행위 당시 기준이고 기본대리권과 같은 종류일 필요가 없으며 복임권 없는 대리인이 선임한 복대리인의 권한이나 소멸한 대리권도 기본대리권이 된다":"정당한 이유는 대리행위 당시를 기준으로 하며 기본대리권은 같은 종류일 필요가 없습니다.","대위 부기등기 없이도 후순위 근저당권자에게 대위할 수 있다":"보증인은 부기등기를 하지 않아도 뒤 순위 근저당권자를 상대로 대위하여 권리를 행사합니다.","대위하지 못한다(제404조 제1항)":"채권자대위권은 일신에 전속한 권리에는 행사할 수 없습니다.","대항요건을 갖추지 못한 양수인의 소, 형사 배상명령 신청, 확정판결 후 재판상 청구 확인의 소도 중단 사유다":"대항요건 없는 양수인의 소, 배상명령 신청, 확정판결 후 확인의 소도 시효 중단 사유입니다.","도난·유실한 날부터 2년 내 반환청구할 수 있으나 금전은 예외다(제250조)":"도품·유실물은 도난·유실한 날부터 2년 안에 반환을 청구할 수 있으나 금전은 예외입니다.","도의관념에 맞으면 반환을 청구하지 못한다(제744조)":"착오로 비채변제를 했어도 도의관념에 맞는 변제라면 반환을 청구하지 못합니다.","동시이행이 아니고 영수증 교부와 변제가 동시이행이다":"채권증서 반환은 동시이행이 아니고 영수증 교부와 변제가 동시이행입니다.","동의 받은 부속물의 매수를 청구할 수 있으나 토지 임차인에게는 부속물매수청구권이 없다(제646조)":"임대인 동의로 설치한 부속물은 건물 임차인이 사 달라고 청구할 수 있지만 토지 임차인은 청구할 수 없습니다.","동일인 소유였던 토지·건물이 매매 등으로 소유자가 달라질 때 인정된다":"관습법상 법정지상권은 같은 사람 소유였던 토지·건물이 매매 등으로 따로 소유될 때 인정됩니다.","동일한 위난으로 2인 이상 사망하면 동시에 사망한 것으로 추정한다(제30조)":"같은 위난으로 2인 이상이 죽으면 누가 먼저 죽었는지 가리지 않고 동시에 사망한 것으로 추정합니다.","등기 없이 성립하는 법정담보물권이다":"유치권은 등기 없이 요건만 갖추면 성립하는 법정담보물권입니다.","등기한 때부터 제3자에게 효력이 있다(제621조)":"임대차는 등기한 때부터 제3자에게 효력이 있습니다.","등기해야 효력이 생긴다(제186조)":"법률행위로 하는 부동산 물권변동은 등기를 해야 효력이 생깁니다.","매도인에게 속하지만 매수인이 대금을 완제하면 인도 전이라도 과실은 매수인에게 속한다":"인도하지 않은 목적물의 과실은 매도인 몫이지만 매수인이 대금을 완제하면 인도 전이라도 매수인 몫이 됩니다.","매수인이 선의·무과실이어야 하고 경매에는 적용되지 않으며(제580조), 안 날부터 6월 내 행사한다(제582조)":"하자담보책임은 매수인이 선의·무과실이어야 하고 경매에는 적용되지 않으며 안 날부터 6월 안에 행사합니다.","매수인이 저당 피담보채무를 인수하고 대금에서 공제하면 원칙적으로 이행인수이고, 이행인수인이 변제하면 채권자를 법정대위할 수 있다":"저당 채무를 매수인이 떠안고 대금에서 빼는 약정은 원칙적으로 이행인수이며 변제하면 채권자의 권리를 대신 행사합니다.","면제·혼동·소멸시효 완성(제419조~제421조)과 상계권자가 상계하지 않을 때 다른 채무자의 상계(제418조 제2항)는 그 채무자의 부담부분 한도에서만 효력이 있다":"면제, 혼동, 소멸시효 완성은 해당 채무자의 부담부분 한도에서만 다른 채무자에게 효력이 있습니다.","면책적인지 불분명하면 병존적 인수로 보고, 병존적 인수는 제3자를 위한 계약이며 부탁받은 인수인과 채무자는 연대채무 관계다":"면책적인지 불분명하면 병존적 인수로 보며 병존적 인수는 제3자를 위한 계약이고 두 사람이 연대채무 관계에 놓입니다.","모든 채권자의 이익을 위해 미치지만(제407조) 사해행위 후에 성립한 채권자는 포함되지 않는다":"취소의 효력은 모든 채권자의 이익을 위해 미치지만 사해행위 후에 성립한 채권자는 제외됩니다.","목적물을 인도하기 전이고 매수인이 대금을 완제하지 않았다면 매도인이 이행지체 중이어도 목적물에서 생긴 과실은 매도인에게 속한다(제587조 관련 판례)":"목적물을 넘기지 않고 대금도 다 받지 못했다면 매도인이 지체 중이어도 과실은 매도인 몫입니다.","목적물을 인도해야 효력이 생기며(제330조), 점유개정으로는 설정할 수 없다":"질권은 목적물을 인도해야 효력이 생기고 점유개정으로는 설정할 수 없습니다.","무과실책임이고 이행·손해배상 선택권은 상대방에게 있으며 제한능력자는 지지 않는다":"무권대리인은 과실이 없어도 책임을 지고 이행·손해배상 선택권은 상대방에게 있으며 제한능력자는 면합니다.","무상계약이고, 차주는 통상의 필요비를 부담하며 대주 승낙 없이 제3자에게 사용하게 하면 대주가 해지할 수 있다(제610조)":"사용대차는 무상계약이며 차주는 통상의 필요비를 부담하고 대주 승낙 없이 제3자가 쓰게 하면 대주가 해지합니다.","무상이어도 선관주의의무를 지고(제681조), 승낙이나 부득이한 사유가 있어야 복위임하며 비용 선급을 청구할 수 있다(제687조)":"수임인은 무상이어도 선관주의의무를 지고 승낙이나 부득이한 사유가 있어야 복위임하며 비용 선급을 청구할 수 있습니다.","무효는 선의의 제3자에게도 주장할 수 있으며 추인으로 유효가 되지 않는다":"반사회질서 무효는 선의 제3자에게도 주장할 수 있고 추인해도 유효로 바뀌지 않습니다.","무효원인이 소멸한 후에 하며 강박으로 취소된 행위도 추인할 수 있다":"무효행위의 추인은 무효 원인이 사라진 뒤 가능하며 강박으로 취소된 행위도 추인할 수 있습니다.","무효인 경매의 매수인 등기말소의무와 근저당권자의 배당금 반환의무도 동시이행이 아니다":"무효가 된 경매에서는 매수인의 등기 말소와 근저당권자의 배당금 반환을 서로 맞바꿀 필요가 없습니다.","묵시적으로도 표시할 수 있으나 표시되지 않으면 동기에 불과하고, 반드시 실현될 사실은 조건이 아니라 기한이다":"조건은 묵시적으로도 표시할 수 있으나 표시되지 않으면 동기에 불과하고 반드시 올 사실은 기한입니다.","물건을 사실상 지배하는 자는 점유권이 있다(제192조)":"점유권은 물건을 사실상 지배하는 사람에게 생깁니다.","물건의 사용대가로 받는 금전 등이다(제101조)":"법정과실은 물건을 쓰게 해 주고 받는 금전 등 대가입니다.","물건의 용법에 따라 수취하는 산출물이다(제101조)":"천연과실은 물건의 용법에 따라 얻는 산출물을 뜻합니다.","물권은 법률 또는 관습법에 의하는 외에는 임의로 창설하지 못한다(제185조)":"물권법정주의에 따라 물권은 법률이나 관습법에 없는 한 당사자가 마음대로 만들 수 없습니다.","물상보증인 상호간은 재산 가액에 비례해 대위하고, 물상보증인은 제3취득자에게 전부 대위하지만 제3취득자는 물상보증인에게 대위하지 못한다":"물상보증인끼리는 재산 가액에 비례해 대위하고 물상보증인은 제3취득자에게 전부 대위하지만 그 반대는 안 됩니다.","미리 포기하지 못하고 완성 후에는 포기할 수 있으며 그때부터 새 시효가 진행한다":"시효이익은 완성 전에는 포기하지 못하고 완성 뒤 포기하면 그때부터 새 시효가 진행합니다.","미성년자와 피한정후견인만 해당하므로, 피성년후견인은 그런 속임수를 써도 취소할 수 있다":"동의가 있는 것처럼 속인 경우는 미성년자와 피한정후견인에 한하고 피성년후견인은 계속 취소할 수 있습니다.","민법은 청약을 철회하지 못한다고만 정하고 철회 예외를 두지 않는다(제527조)":"청약은 도달한 뒤 청약자가 마음대로 거두어들일 수 없다는 것이 민법의 태도입니다.","민사 법정이율은 연 5푼(5%), 상사는 연 6%다":"민사 법정이율은 연 5푼이고 상사는 연 6%입니다.","민사에 관하여 법률에 규정이 없으면 관습법, 관습법이 없으면 조리에 의한다(제1조)":"민사에서 법률이 없으면 관습법을, 관습법도 없으면 조리를 재판 기준으로 삼는 순서입니다.","반환과 손해배상을 침탈당한 날부터 1년 내에 청구한다(제204조)":"점유를 빼앗기면 침탈당한 날부터 1년 안에 반환과 손해배상을 청구해야 합니다.","반환시기 약정이 없는 소비대차는 상당한 기간을 정해 최고해야 지체가 된다":"빌린 돈의 반환시기를 정하지 않았다면 상당 기간을 주고 독촉한 뒤에야 연체 책임이 생깁니다.","반환을 청구하지 못하며(제742조), 몰랐다면 과실이 있어도 이 조항이 적용되지 않는다":"채무가 없음을 알고 변제하면 반환을 청구하지 못하고 몰랐다면 과실이 있어도 이 조항이 적용되지 않습니다.","반환을 청구하지 못하지만 착오로 변제했으면 채권자는 얻은 이익을 반환한다(제743조)":"기한 전 변제는 반환을 청구하지 못하나 착오로 변제했다면 채권자가 얻은 이익을 돌려줍니다.","받은 날부터 이자를 붙이지만(제548조 제2항) 합의해제에는 이 규정이 적용되지 않는다":"해제로 반환할 금전에는 받은 날부터 이자를 붙이지만 합의해제에는 이 규정이 적용되지 않습니다.","받은 이익에 이자를 붙이고 손해를 배상한다(제748조)":"악의 수익자는 받은 이익에 이자를 붙여 반환하고 손해가 있으면 배상합니다.","방해가 끝난 날부터 1년 내에 한다(제205조)":"점유 방해제거 청구는 방해가 끝난 날부터 1년 안에 해야 합니다.","법률상 원인 없이 타인의 재산이나 노무로 이익을 얻고 그로 인해 타인에게 손해를 가해야 한다(제741조)":"부당이득은 법률상 원인 없이 타인의 재산이나 노무로 이익을 얻고 타인에게 손해를 입힐 때 성립합니다.","법률상 원인이 없다는 점을 반환을 청구하는 사람이 증명한다":"급부부당이득에서는 법률상 원인이 없다는 점을 반환을 구하는 사람이 증명해야 합니다.","법률의 착오, 매도인이 해제한 뒤, 하자담보책임이 성립할 때도 착오 취소가 가능하지만 소송행위는 취소할 수 없다":"법률의 착오나 해제 후, 담보책임 성립 때도 착오 취소가 가능하나 소송행위는 취소할 수 없습니다.","법률행위 내용의 중요부분 착오면 취소할 수 있고 중대한 과실은 상대방이 증명한다(제109조)":"착오 취소는 내용의 중요부분에 착오가 있을 때 가능하며 표의자의 중과실은 상대방이 증명합니다.","법률행위로 할 수는 없고 단축·경감은 할 수 있다(제184조)":"시효를 배제·연장·가중하는 약정은 허용되지 않고 단축·경감하는 약정만 할 수 있습니다.","법원의 허가가 있어야 하고 보전행위는 허가 없이 한다(제404조 제2항)":"피보전채권의 기한이 오기 전에는 법원 허가가 필요하나 보전행위는 허가 없이 할 수 있습니다.","법원이 감액하고(제398조), 위약금 약정은 예정으로 추정한다":"예정액이 지나치게 많으면 법원이 줄일 수 있고 위약금 약정은 예정으로 추정합니다.","법원이 아니어서 당사자가 주장·증명해야 하며 임의규정이 있을 때 법률행위 해석기준이 된다":"사실인 관습은 법원이 아니라 당사자가 주장하고 증명해야 하며 임의규정이 있을 때 해석 기준이 됩니다.","법적 작위의무가 객관적으로 인정되면 의무자가 그 존재를 몰랐어도 성립한다":"지켜야 할 법적 행위의무가 객관적으로 있었다면 의무자가 그 사실을 몰랐더라도 부작위 불법행위가 성립합니다.","법정대리인의 선의·악의와 관계없이 현존이익이다(제141조)":"취소 후 반환 범위는 법정대리인이 선의든 악의든 이익이 현재 남아 있는 한도입니다.","법정이율, 약정이율이 있으면 그 이율에 따르고 채권자는 손해를 증명할 필요가 없으며 채무자는 과실 없음을 항변하지 못한다(제397조)":"금전채무 불이행의 배상은 법정이율이나 약정이율에 따르며 채권자는 손해를 증명할 필요가 없습니다.","법정책임이어서 채권자의 귀책사유가 필요 없다":"채권자지체는 법이 정한 책임이어서 채권자의 귀책사유가 없어도 성립합니다.","변제기 전에도 상대방의 손해를 배상하고 변제할 수 있으며(제468조), 변제기 전에 변제한 채무자는 반환을 청구하지 못한다":"변제기 전에도 상대방 손해를 배상하고 변제할 수 있으나 일찍 변제한 채무자는 반환을 청구하지 못합니다.","변제는 채무내용에 좇은 현실제공으로 한다":"변제의 제공은 채무내용에 맞게 현실로 해야 합니다.","변제자가 권한 없음을 알았거나 알 수 있었으면 효력이 없다(제471조)":"영수증 소지자에게 한 변제는 권한 없음을 알았거나 알 수 있었다면 효력이 없습니다.","변제자가 선의·무과실일 때 효력이 있다(제470조)":"채권의 준점유자에게 한 변제는 변제자가 선의·무과실일 때 효력이 있습니다.","변제한 가액에 비례해 채권자와 함께 권리를 행사하고 저당권을 준공유하며 채권자는 저당권 일부이전 부기등기를 해 줄 의무가 있다":"일부 변제한 대위자는 채권자와 저당권을 함께 가지며 채권자에게는 일부이전 부기등기를 해 줄 의무가 있습니다.","보수 관행이 있으면 명시적 합의가 없어도 보수를 청구할 수 있다":"보수를 주고받는 관행이 있는 일이면 약속을 따로 적지 않아도 일한 사람이 보수를 요구할 수 있습니다.","보존행위와 성질을 바꾸지 않는 이용·개량행위만 한다(제118조)":"권한을 정하지 않은 대리인은 보존행위와 성질을 바꾸지 않는 이용·개량행위만 할 수 있습니다.","보증인 유무가 변제이익에 차이를 주지 않으므로 이율이 높은 채무가 변제이익이 크다":"보증인이 있든 없든 변제이익이 같다면 이자율이 더 높은 채무를 먼저 갚는 것이 변제이익이 큽니다.","보증인은 주채무 시효소멸을 주장할 수 없다":"부종성을 부정할 특별한 사정이 있으면 보증인은 주채무 시효소멸을 주장하지 못합니다.","보증인의 기명날인 또는 서명이 있는 서면으로 해야 효력이 생기고 전자적 형태는 효력이 없으며(제428조의2), 기명날인은 타인이 대행할 수 있다":"보증은 보증인의 기명날인이나 서명이 있는 서면으로 해야 하고 전자적 형태는 효력이 없으며 기명날인은 대행할 수 있습니다.","보증채권만 주채권과 분리해 양도할 수 없고, 주채권에 대항요건을 갖추면 보증채권에도 효력이 미친다":"보증채권만 따로 양도하는 것은 안 되고 주채권에 대항요건을 갖추면 보증채권에도 효력이 미칩니다.","보통실종 5년, 특별실종 1년이고 실종기간이 만료한 때에 사망한 것으로 본다(제27조·제28조)":"실종선고는 실종기간이 끝난 때에 사망한 것으로 보며 보통실종은 5년, 특별실종은 1년입니다.","보험금 부정취득 목적의 다수 보험계약":"보험금을 부정하게 타 내려고 맺은 여러 보험계약은 반사회질서 법률행위로 무효입니다.","본인의 의사를 고려하여야 한다":"한정후견은 본인 의사를 고려해야 하는 제도입니다.","본인의 의사에 반하여 할 수 없다":"특정후견은 본인의 의사에 반해서는 할 수 없습니다.","부담의 한도에서 매도인과 같은 담보책임을 진다(제559조)":"부담부 증여는 부담의 한도에서 매도인과 같은 담보책임을 집니다.","부동산도 종물이 될 수 있고, 주유소 지하에 매설한 유류저장탱크는 토지의 종물이 아니다":"건물 같은 부동산도 종물이 될 수 있으나 땅속에 묻은 주유소 탱크는 토지의 종물로 취급하지 않습니다.","부동산을 사용·수익하고 전세금 우선변제를 받으며 농경지는 목적으로 하지 못한다(제303조)":"전세권자는 부동산을 사용·수익하며 전세금을 우선변제받으나 농경지는 목적으로 하지 못합니다.","부첩관계 종료를 해제조건으로 한 증여":"부첩관계 종료를 해제조건으로 한 증여는 사회질서에 반해 무효입니다.","부탁 없는 보증인은 그 당시 이익을 받은 한도, 주채무자의 의사에 반한 보증인은 현존이익 한도에서 구상한다(제444조)":"부탁 없는 보증인은 당시 이익 한도로, 주채무자 의사에 반한 보증인은 현존이익 한도로 구상합니다.","부합물과 종물에 미치고(제358조), 과실에는 압류 후에 미친다(제359조)":"저당권은 부합물과 종물에 미치고 과실에는 압류한 뒤부터 미칩니다.","분열이 인정되지 않아 재산은 잔존 교인의 총유이고, 성년 여자도 종원이 된다":"교회는 분열이 인정되지 않으므로 재산은 남은 교인의 총유이고 성년 여자도 종원이 됩니다.","불법의 원인으로 급여한 것은 반환을 청구하지 못하지만 불법원인이 수익자에게만 있으면 청구할 수 있다(제746조)":"불법적 이유로 준 것은 돌려받지 못하지만 불법의 책임이 받은 쪽에만 있다면 돌려달라고 할 수 있습니다.","불법행위 손해배상채무는 최고 없이 성립과 동시에 지체가 되고, 고의의 불법행위자는 그 채무를 수동채권으로 상계하지 못한다(제496조)":"불법행위 배상채무는 독촉 없이 사고 때부터 지체가 되고 일부러 해친 사람은 이를 상계로 정리하지 못합니다.","비법인사단 대표자의 불법행위에도 적용된다":"법인의 불법행위 책임 규정은 비법인사단 대표자의 불법행위에도 적용됩니다.","사기는 기망의 위법성, 강박은 강박의 고의가 요건이다":"사기로 인한 취소는 속이는 행위가 위법해야 하고 강박으로 인한 취소는 겁을 주려는 고의가 있어야 합니다.","사망·파산·수임인의 성년후견개시로 위임이 종료한다(제690조)":"위임은 당사자의 사망·파산이나 수임인의 성년후견개시로 종료합니다.","사소한 파손은 수선의무가 없고, 수선으로 사용에 지장이 생기면 그 한도에서 차임을 거절할 수 있다":"사소한 파손은 임대인이 고칠 의무가 없고 수선 때문에 못 쓰는 만큼은 임차인이 차임을 거절할 수 있습니다.","사실상 대표하여 사무를 집행하는 사람도 포함된다":"대표기관에는 직함이 없어도 사실상 대표해 사무를 집행하는 사람이 들어갑니다.","사용자는 피해자의 과실을 들어 감경을 주장할 수 있다":"피용자가 고의로 재물을 가로챈 경우에도 사용자는 피해자의 과실을 들어 배상액을 줄여 달라고 주장할 수 있습니다.","사용자에게 직접 지급을 청구할 수 없다":"임금채권을 양수한 사람은 사용자에게 직접 지급을 청구할 수 없습니다.","사용자의 피용자에 대한 구상권은 신의칙상 제한될 수 있다":"사용자가 손해를 갚은 뒤 피용자에게 되묻는 권리는 신의칙에 비추어 일정 범위로 줄어들 수 있습니다.","사해행위 전 성립 채권을 사해행위 후 양수하거나 대항요건을 사해행위 후에 갖춘 양수인도 행사할 수 있다":"사해행위 전에 성립한 채권을 후에 양수하거나 대항요건을 후에 갖춘 양수인도 취소권을 행사할 수 있습니다.","사해행위 전에 성립한 채권이어야 하지만 기초 법률관계가 있고 성립 개연성이 높으면 이후 채권도 된다":"피보전채권은 사해행위 전에 성립해야 하나 기초 법률관계가 있고 성립이 거의 확실하면 이후 채권도 가능합니다.","상당한 기간 내에 승낙 통지를 받지 못하면 효력을 잃는다(제529조)":"승낙기간을 정하지 않은 청약은 상당 기간 내에 승낙 통지를 받지 못하면 효력을 잃습니다.","상당한 기간을 정해 최고하고 그 기간이 지나야 지체가 된다":"반환시기 약정이 없는 소비대차는 상당 기간을 정한 최고가 지나야 지체가 됩니다.","상당한 기간을 정해 최고한 뒤 해제하고, 미리 이행거절 의사를 표시하면 최고와 자기 채무의 이행제공이 필요 없다(제544조)":"이행지체 해제는 상당 기간을 정해 최고한 뒤에 하며 미리 이행거절 의사를 밝혔다면 최고와 자기 이행제공이 필요 없습니다.","상당한 담보를 제공하고 유치권 소멸을 청구할 수 있다(제327조)":"채무자는 상당한 담보를 제공하고 유치권 소멸을 청구할 수 있습니다.","상대방과의 합의가 필요하며 무효이지만 사해행위 취소의 대상이 된다":"통정허위표시는 상대방과 합의해야 하고 무효이지만 사해행위 취소의 대상이 될 수 있습니다.","상대방 동의가 없으면 무효이고, 악의의 상대방도 최고는 할 수 있으나 철회는 못 한다":"일부만 추인하려면 상대방 동의가 필요하고 악의의 상대방도 최고는 해도 철회는 못 합니다.","상대방의 이행이 곤란할 현저한 사유가 있으면 이행을 거절할 수 있다(제536조 제2항)":"선이행의무자도 상대방의 이행이 곤란할 현저한 사유가 있으면 이행을 거절할 수 있습니다.","상대방의 이행제공이 있을 때까지 항변권을 행사하지 않아도 이행지체 책임을 지지 않는다":"동시이행 관계에서는 상대방이 이행을 제공할 때까지 항변권을 행사하지 않아도 지체책임이 없습니다.","상대방이 선의·무과실이어야 하고 직함 사용 묵인으로도 수여표시가 인정된다":"수여표시 표현대리는 상대방이 선의·무과실이어야 하며 직함 사용을 묵인한 것도 수여표시로 봅니다.","상대방이 완결 의사를 표시하는 때 매매의 효력이 생긴다(제564조)":"일방예약은 상대방이 완결 의사를 표시하는 때 매매의 효력이 생깁니다.","상속·공용징수·판결·경매 등은 등기 없이 효력이 생기지만 등기하지 않으면 처분하지 못한다(제187조)":"법률 규정에 따른 취득은 등기 없이 효력이 생기지만 등기해야 처분할 수 있습니다.","상속재산 분할협의, 시효이익 포기, 통정허위표시":"상속재산 분할협의, 시효이익 포기, 통정허위표시도 사해행위가 될 수 있습니다.","서면에 의하지 않은 증여, 수증자의 범죄행위·부양의무 불이행, 증여자의 재산상태 현저한 변경은 해제 사유이지만 이미 이행한 부분에는 영향이 없다(제555조~제558조)":"서면 없는 증여, 수증자의 범죄·부양의무 불이행, 증여자의 재산 악화는 해제 사유이나 이행한 부분은 영향이 없습니다.","선거일 전 3년간처럼 초일 불산입 원칙을 따라 선거일 전날부터 센다":"거꾸로 세는 기간도 초일 불산입을 따라 선거일 전날부터 세어 올라갑니다.","선량한 관리자의 주의로 점유하고 채무자 승낙 없이 사용·대여·담보제공을 하지 못하며 보존에 필요한 사용은 할 수 있다(제324조)":"유치권자는 선관주의로 점유하고 채무자 승낙 없이 사용·대여·담보제공을 못 하며 보존에 필요한 사용은 가능합니다.","선발·일반적 지휘감독에 주의를 다하지 않았으면 책임을 진다":"파견사업주는 선발과 일반적 지휘감독에 주의를 다하지 않았다면 책임을 집니다.","선의 매수인이 대금감액 등을 청구한다(제574조)":"수량지정 매매에서 수량이 부족하면 선의 매수인이 대금감액 등을 청구합니다.","선의 매수인이 해제하고(제575조)":"제한물권이나 유치권 때문에 목적을 이룰 수 없으면 선의 매수인이 해제할 수 있습니다.","선의면 족하고 무과실은 필요 없으며 선의가 추정된다":"허위표시를 몰랐다면 보호되며 과실 유무는 따지지 않고 선의는 이미 있는 것으로 추정됩니다.","선의의 점유자도 소가 제기된 때부터 악의로 본다":"본권 소송에서 패소한 선의 점유자는 소가 제기된 때부터 악의로 간주합니다.","선의의 제3자에게 대항하지 못하며 경과실로 모른 양수인은 선의로 취급한다(제449조)":"양도금지특약은 선의 제3자에게 맞서지 못하며 경과실로 몰랐던 양수인도 선의로 취급합니다.","선의 점유자는 과실을 취득하고 악의 점유자는 과실을 반환하거나 대가를 보상한다(제201조)":"선의 점유자는 점유물에서 난 과실을 가져도 되지만 악의 점유자는 돌려주거나 값을 물어야 합니다.","설치·보존의 하자로 인한 손해는 1차로 점유자가 배상하고, 점유자가 필요한 주의를 다했으면 소유자가 배상한다(제758조)":"공작물 하자로 생긴 손해는 먼저 점유자가 배상하고 점유자가 주의를 다했으면 소유자가 배상합니다.","성년후견 심판 때 가정법원은 취소할 수 없는 법률행위의 범위를 정할 수 있고, 일상생활에 필요하고 대가가 과도하지 않은 행위는 취소할 수 없다":"성년후견에서는 가정법원이 취소 불가 범위를 정할 수 있고 일상생활 행위는 취소하지 못합니다.","성립하지 않는다(제320조)":"점유가 불법행위로 시작되었다면 유치권은 성립하지 않습니다.","성폭력·성추행 등 성적 침해를 당하면 성년이 될 때까지 시효가 진행하지 않는다":"미성년자가 성적 침해를 당하면 성년이 될 때까지 소멸시효가 진행하지 않습니다.","소멸 통고 후 6월이 지나면 소멸한다(제313조)":"기간을 정하지 않은 전세권은 소멸 통고 후 6월이 지나면 소멸합니다.","소비 여부와 관계없이 현존하는 것으로 추정한다":"금전 이득은 소비했는지와 무관하게 현존하는 것으로 추정합니다.","소유권과 분리해 양도하지 못한다":"물권적 청구권은 소유권에 딸린 권리라서 소유권과 떼어 양도할 수 없습니다.","소유자로 등기된 자가 10년간 선의·무과실로 점유하면 된다(제245조)":"등기부취득시효는 소유자로 등기된 사람이 10년간 선의·무과실로 점유하면 완성됩니다.","소 제기 시부터 소급해 6월 이내에 한 최고 때 중단된다(제174조)":"최고를 거듭하다 소를 내면 소 제기 시점에서 거슬러 6월 안에 한 최고 때 중단됩니다.","손해가 없었다는 증명으로는 면책되지 않지만 귀책사유 없음을 증명하면 면책된다":"배상액을 미리 정한 경우 채무자는 손해가 없었다고 해도 면책되지 않고 귀책사유가 없음을 입증해야 합니다.","손해 및 가해자를 안 날부터 3년, 불법행위를 한 날부터 10년이다(제766조)":"불법행위 소멸시효는 손해와 가해자를 안 날부터 3년, 불법행위를 한 날부터 10년입니다.","손해배상액의 예정으로서 감액 대상이 된다":"지연손해금 비율을 정한 약정은 손해배상액의 예정으로 보아 감액 대상이 됩니다.","손해배상청구권에 관해 이미 출생한 것으로 보지만(제762조) 모체 안에서 사망한 태아는 청구권이 없다":"태아는 손해배상청구권에 관해서는 이미 태어난 것으로 보지만 모체 안에서 죽은 태아에게는 청구권이 없습니다.","손해 전액에서 과실비율로 감액한 잔액이 청구액을 넘지 않으면 그 잔액을 인용한다":"일부청구에서는 손해 전액에서 과실비율만큼 줄인 잔액이 청구액보다 크지 않으면 그 잔액을 인정합니다.","수량지정 매매의 면적 부족이나 의사 불합치로 계약이 불성립한 경우":"수량지정 매매의 면적 부족이나 의사 불합치로 불성립한 경우에는 계약체결상의 과실 책임을 묻지 못합니다.","수익자에게 양도 취소 통지를 하도록 청구한다":"채권양도가 취소되면 수익자에게 양도 취소 통지를 하라고 청구합니다.","수익자의 불법성이 현저히 크고 급여자의 불법성이 경미하면 반환청구가 허용된다":"준 사람의 잘못은 작고 받은 사람의 잘못이 훨씬 크면 신의상 반환을 구하는 것이 허용됩니다.","순서로 충당하며 채무자가 원본 먼저 충당을 지정할 수 없다(제479조)":"비용, 이자, 원본의 순서로 충당하며 채무자가 원본부터 충당하라고 지정할 수는 없습니다.","승낙으로 인정되는 사실이 있는 때 성립한다(제532조)":"의사실현은 승낙으로 인정되는 사실이 있는 때 계약이 성립합니다.","승낙 통지를 발송한 때 성립한다(제531조)":"격지자간 계약은 승낙 통지를 발송한 때 성립합니다.","시기와 관계없이 변제금액에 비례해 배당받는다":"여러 사람이 시기를 달리해 일부씩 대위변제하면 시기와 무관하게 변제 금액에 비례해 배당받습니다.","시정에 지나치게 많은 비용이 들면 시정을 청구하지 못하며 담보책임은 종료일부터 6개월 내 행사하고 여행자에게 불리한 약정만 무효다":"시정에 지나치게 많은 비용이 들면 시정을 청구할 수 없고 담보책임은 종료일부터 6개월 안에 행사하며 불리한 약정만 무효입니다.","신의칙상 작위의무, 사용자의 구상권 제한, 상계권 남용 제한(주관적 요건 불요)이 판례로 인정된다":"판례는 신의칙에 따라 일정한 작위의무를 인정하고 구상권과 상계권 행사에 한계를 둡니다.","신체·자유·명예 침해에는 위자료를 배상하고, 생명침해 시 직계존속·직계비속·배우자는 재산상 손해가 없어도 위자료를 청구한다(제751조·제752조)":"신체·자유·명예 침해에는 위자료가 인정되고 생명침해 시 가족은 재산상 손해가 없어도 위자료를 청구합니다.","실질적인 지휘·감독 관계가 필요하고, 외형상 사무집행으로 보이면 행위자의 주관적 사정과 관계없이 사무집행에 관한 행위다":"사용자책임은 실질적 지휘·감독 관계가 필요하고 외형상 사무집행으로 보이면 행위자의 주관적 사정과 무관하게 인정됩니다.","쌍방이 균분한다(제566조)":"매매비용은 당사자 쌍방이 똑같이 나누어 부담합니다.","쌍방 책임 없는 사유로 불능이 되면 채무자는 상대방의 이행을 청구하지 못한다(제537조)":"쌍방 책임 없는 사유로 불능이 되면 채무자는 상대방의 이행을 청구하지 못하는 것이 위험부담입니다.","악의라도 현존이익만 반환한다":"제한능력자는 악의여도 현존이익만 반환하면 됩니다.","악의 매수인도 해제할 수 있으나 손해배상은 선의만 청구한다(제570조)":"전부 타인 권리의 매매에서는 악의 매수인도 해제할 수 있으나 손해배상은 선의 매수인만 청구합니다.","악의여도 해제할 수 있다(제576조)":"저당권·전세권 실행으로 소유권을 잃으면 악의여도 해제할 수 있습니다.","악의일 때만 행사할 수 있다":"침탈자의 특별승계인에게는 승계인이 악의일 때만 점유 반환을 청구할 수 있습니다.","악의 점유자는 손해 전부, 선의 점유자는 현존이익 한도에서 배상하되 소유의 의사가 없으면 선의여도 전부 배상한다(제202조)":"점유물을 멸실·훼손하면 악의는 전부, 선의는 현존이익 한도로 배상하나 소유 의사가 없으면 전부 배상합니다.","압류 같은 공법상 처분에도 적용되고, 건물과 그 부지의 토지임차권, 원본채권과 이자채권처럼 권리 상호간에도 유추적용된다":"종물 법리는 압류 같은 공법상 처분에도 적용되고 권리 사이에도 유추 적용됩니다.","압류·전부명령으로는 이전되고, 전부채권자에게서 양수한 자는 악의여도 채무자가 무효를 주장하지 못한다":"양도금지특약이 있어도 압류·전부명령으로는 이전되고 전부채권자에게서 산 사람에게는 채무자가 무효를 주장하지 못합니다.","약정 계약금의 배액을 상환해야 하고, 해약권 배제 약정이 있으면 해약금 해제를 할 수 없다":"계약금 일부만 받았다면 약정 계약금의 배액을 상환해야 하고 해약권 배제 약정이 있으면 해약금 해제를 못 합니다.","양도인의 통지나 채무자의 승낙이 있어야 채무자에게 대항하고, 확정일자 있는 증서여야 채무자 외의 제3자에게 대항한다(제450조)":"채권양도는 양도인의 통지나 채무자의 승낙이 있어야 채무자에게 대항하고 확정일자 있는 증서로 제3자에게 대항합니다.","양수인이 채무자에게 해제 사실을 통지해야 양도인이 대항할 수 있다":"양도계약이 해제되면 양수인이 채무자에게 해제 사실을 통지해야 양도인이 맞설 수 있습니다.","양 청약이 모두 도달한 때(제533조)":"교차청약은 두 청약이 모두 도달한 때 계약이 성립합니다.","여러 명이 가분채무를 지면 특별한 의사표시가 없는 한 균등한 분할채무가 된다(제408조)":"가분채무를 여럿이 지면 특별한 의사표시가 없는 한 균등한 분할채무가 됩니다.","여러 명이 타인의 재산을 함께 사용해 생긴 부당이득반환채무는 불가분채무이고, 출재로 공동면책한 불가분채무자는 다른 채무자의 부담부분을 구상할 수 있다":"함께 남의 재산을 써서 진 부당이득 반환 채무는 나눌 수 없는 채무이고 공동면책한 사람은 구상할 수 있습니다.","역에 따라 계산하며 처음부터 기산하지 않으면 최후의 주·월·연에서 기산일에 해당한 날의 전일로 만료한다(제160조)":"주·월·연은 달력으로 계산하며 중간에서 시작하면 마지막 주·월·연에서 기산일에 해당한 날의 전날 만료합니다.","연대채무자 전원의 부탁으로 연대보증한 사람은 변제 후 어느 연대채무자에게나 전액을 구상할 수 있다":"전원의 부탁을 받아 연대보증한 사람은 변제한 뒤 어느 채무자에게든 전액 구상할 수 있습니다.","연대하여 배상하고 교사자·방조자도 공동행위자로 본다(제760조)":"공동불법행위자는 연대하여 배상하고 교사자와 방조자도 공동행위자로 봅니다.","연대하여 의무를 진다(제616조)":"공동차주는 사용대차에서 연대하여 의무를 집니다.","완성 전 손해를 배상하고 해제할 수 있으며 이때 과실상계를 주장하지 못한다(제673조)":"도급인은 완성 전에 손해를 배상하고 해제할 수 있으며 이때 과실상계를 주장하지 못합니다.","완성 후에도 상계할 수 있고(제495조), 확정된 벌금채권도 자동채권이 된다":"시효 완성 전에 상계적상에 있었다면 완성 후에도 상계할 수 있고 확정된 벌금채권도 자동채권이 됩니다.","외부에 표시될 필요가 없고 자기 이익을 위한 의사와 함께 있어도 된다":"타인을 위한 의사는 밖으로 드러낼 필요가 없고 자기 이익을 위한 의사와 함께 있어도 됩니다.","요역지 소유권에 부종해 이전하고 요역지와 분리해 양도하지 못한다(제292조)":"지역권은 요역지 소유권에 딸려 함께 이전되며 요역지와 따로 양도하지 못합니다.","원물에서 분리하는 때 수취권자에게 속한다(제102조)":"천연과실은 원물에서 떨어질 때 수취할 권리자의 것이 됩니다.","원본 이행기일을 지난 후 1년분에 한해 담보한다(제360조)":"저당권은 지연배상을 원본 이행기일을 지난 후 1년분에 한해 담보합니다.","원본채권을 양도해도 이미 변제기에 이른 이자채권은 함께 넘어가지 않는다":"원본채권을 넘기더라도 이미 변제기가 된 이자채권은 따로 남아 함께 넘어가지 않습니다.","원상회복만 구해도 법원은 가액배상을 명할 수 있고, 제3자가 저당권을 취득했어도 그 피담보채권액을 빼지 않고 가액배상을 명한다":"원상회복만 구해도 법원이 가액배상을 명할 수 있으며 제3자의 저당권이 있어도 그 피담보채권액을 빼지 않습니다.","원시적·객관적 전부불능인 계약에서 불능을 알았거나 알 수 있었던 자는 선의·무과실의 상대방이 받은 신뢰손해를 배상하되 이행이익을 넘지 못한다(제535조)":"계약체결상의 과실은 전부 불능인 계약에서 알았거나 알 수 있었던 자가 선의·무과실 상대방의 신뢰손해를 이행이익 한도로 배상하는 책임입니다.","원시적 불능이 아니어서 유효하다":"타인 물건의 매매는 원시적 불능이 아니어서 유효합니다.","원인된 법률관계가 끝나면 대리권이 소멸한다(제128조)":"대리권은 그 바탕이 된 법률관계가 끝나면 함께 소멸합니다.","원칙적으로 책임이 없지만(제757조) 수급인의 일을 구체적으로 지휘·감독했으면 사용자책임을 진다":"도급인은 수급인 일에 책임지지 않는 것이 원칙이나 일을 직접 구체적으로 지시했다면 사용자책임이 따릅니다.","원칙적으로 해제권을 발생시키지 않는다":"부수의무 위반은 원칙적으로 해제권을 생기게 하지 않습니다.","위약금·배상액 예정이 금지된다":"근로계약에서는 위약금이나 배상액 예정을 정하는 것 자체가 금지됩니다.","유체의 귀속은 제사주재자에게 있다":"유체는 제사주재자가 귀속 주체가 되어 장례와 매장을 정합니다.","음식료·숙박료, 동산 사용료, 노역인·연예인 임금은 1년이다(제164조)":"음식료·숙박료, 동산 사용료, 노역인·연예인 임금은 1년 단기시효에 걸립니다.","의무 없이 타인을 위해 사무를 관리해야 한다":"사무관리는 법적 의무 없이 타인을 위해 사무를 관리할 때 성립합니다.","의무위반과 손해 사이에 상당인과관계가 있으면 일반불법행위책임을 진다":"책임능력 있는 미성년자의 감독의무자는 의무위반과 손해 사이에 상당인과관계가 있으면 일반불법행위책임을 집니다.","의무의 중대한 위반도 해지의 부득이한 사유다(제661조)":"의무의 중대한 위반도 계약 해지의 부득이한 사유에 해당합니다.","이득자는 있어도 성립하지 않는다":"이득을 본 사람이 있어도 손실을 입은 사람이 없으면 부당이득은 성립하지 않습니다.","이를 변경·소멸시키지 못하지만 미리 유보했으면 할 수 있다(제541조)":"수익자 권리가 생긴 뒤에는 당사자가 바꾸거나 없앨 수 없으나 계약에서 미리 유보했다면 가능합니다.","이미 다른 사람에게 양도되었다는 사실로는 대항할 수 있다":"이의를 보류하지 않은 승낙을 해도 이미 다른 사람에게 양도되었다는 사실로는 대항할 수 있습니다.","이익을 받은 뒤 원인 없음을 알면 그때부터 악의이고, 선의 수익자가 패소하면 소를 제기한 때부터 악의로 본다(제749조)":"악의의 시작 시점은 원인 없음을 안 때이고 선의의 수익자라도 패소하면 소를 낸 때부터 악의로 간주합니다.","이자가 아니라 손해배상금이므로 3년 단기시효가 적용되지 않는다":"지연손해금은 이자가 아닌 손해배상금이어서 3년 단기시효가 적용되지 않습니다.","이자·급료 등 1년 이내 정기급부, 의사·약사의 치료 채권, 도급받은 자의 공사 채권은 3년(제163조)":"이자·급료 같은 정기급부, 의사·약사 치료채권, 공사채권은 단기 3년 소멸시효입니다.","이행기가 도래한 채무, 변제이익이 많은 채무, 이행기가 먼저 도래한 채무 순이고 모두 같으면 채무액에 비례한다(제477조)":"법정충당은 이행기가 온 채무, 변제이익이 큰 채무, 이행기가 먼저 온 채무 순이고 모두 같으면 채무액에 비례합니다.","이행기가 아니라 현실 지급 시의 환금시가로 환산한다(제378조)":"우리나라 통화로 갚을 때는 이행기가 아니라 실제 지급하는 때의 환금시가로 환산합니다.","이행기의 현상대로 인도한다(제462조)":"특정물 인도는 이행기에 있는 그대로의 상태로 하면 됩니다.","이행대행자를 쓸 수 있고, 하자보수에 갈음한 손해배상과 동시이행으로 거절할 수 있는 보수는 그 배상액 상당액에 한하며 그 배상액은 청구 시 기준이다":"수급인은 이행대행자를 쓸 수 있고 하자보수에 갈음한 배상과 동시이행으로 거절할 보수는 그 배상액 상당액이며 청구 시를 기준으로 합니다.","이행된 부분도 원상회복하고, 부담의 존재는 주장하는 자가 증명한다":"부담 불이행으로 해제하면 이행된 부분도 원상회복하고 부담이 있다는 점은 주장하는 사람이 증명합니다.","이행·이행청구·경개·담보제공·양도·강제집행이고 이의를 보류하면 추인이 아니다(제145조)":"법정추인 사유는 이행, 이행청구, 경개, 담보제공, 양도, 강제집행이며 이의를 보류하면 추인이 아닙니다.","이행제공하면 족하고 공탁할 필요는 없다":"배액 상환은 이행제공만으로 충분하고 공탁까지 할 필요는 없습니다.","이행청구(제416조), 경개(제417조), 상계(제418조 제1항), 채권자지체(제422조)는 다른 연대채무자 전원에게 효력이 있다":"이행청구, 경개, 상계, 채권자지체는 다른 연대채무자 전원에게도 효력이 미치는 절대적 효력 사유입니다.","이행청구를 받은 때부터 지체가 된다":"확정된 지연손해금채무는 이행청구를 받은 때부터 지체가 됩니다.","이행청구를 받은 때부터 지체책임을 진다(제387조)":"기한이 없는 채무는 이행청구를 받은 때부터 지체책임이 생깁니다.","인도할 때까지 선량한 관리자의 주의로 보존하며(제374조), 임차목적물 반환채무도 특정물채무다":"특정물 인도채무자는 인도할 때까지 선관주의로 보존해야 하며 임차물 반환채무도 이에 속합니다.","인도해야 효력이 생긴다(제188조 제1항)":"동산 물권의 양도는 인도해야 효력이 생깁니다.","일방이 이행에 착수할 때까지 교부자는 포기, 수령자는 배액 상환으로 해제할 수 있다(제565조)":"한쪽이 이행에 착수하기 전까지 교부자는 계약금을 포기하고 수령자는 배액을 상환해 해제할 수 있습니다.","일부 면제를 받은 연대채무자의 잔존 채무가 자기 부담부분 이상이면 다른 채무자의 채무는 줄지 않는다":"면제받고 남은 채무가 부담부분 이상이면 다른 연대채무자의 채무에는 아무 영향이 없습니다.","임금채권 등을 수동채권으로 하는 상계도 금지된다(제497조)":"임금채권 같은 압류금지채권을 수동채권으로 삼는 상계는 금지됩니다.","임대인의 해지통고는 6월, 임차인은 1월 후 효력이 생긴다(제635조)":"기간 약정이 없으면 임대인의 해지통고는 6월, 임차인의 해지통고는 1월 후에 효력이 생깁니다.","임대차 종료 후 목적물 반환 시 보증금에서 당연히 공제된다":"연체차임은 임대차 종료 후 목적물을 반환할 때 보증금에서 당연히 공제됩니다.","임대할 권한이 없어도 임대차는 유효하고 영구 임대차도 가능하며 처분권한 없는 자의 건물 임대차는 3년을 넘지 못한다(제619조)":"임대차는 임대 권한이 없어도 성립하고 영구 임대차도 가능하며 처분권 없는 자의 건물 임대차는 3년이 한도입니다.","임의규정이므로 특약으로 종물을 처분에서 뺄 수 있다":"종물 처분 규정은 임의규정이어서 당사자가 특약으로 종물을 제외할 수 있습니다.","임의대리인은 본인 승낙이나 부득이한 사유가 있어야 복대리인을 선임한다(제120조)":"임의대리인은 본인의 승낙이나 부득이한 사유가 있어야 복대리인을 선임할 수 있습니다.","임차권 보전을 위해 임대인의 제3자에 대한 인도청구권을 대위할 수 있으나, 임대인 동의 없는 임차권 양수인은 임대인의 권리를 대위하지 못한다":"임차인은 임차권 보전을 위해 임대인의 인도청구권을 대위할 수 있으나 동의 없는 양수인은 대위하지 못합니다.","임차인은 원상회복의무를 진다":"임대인 귀책으로 해지되더라도 임차인은 원상회복의무를 집니다.","임차인이 선관주의를 다했음을 증명해야 면책된다":"원인 불명의 화재로 멸실되면 임차인이 선관주의를 다했음을 증명해야 책임을 면합니다.","입목법에 따라 등기된 수목이나 명인방법을 갖춘 수목은 토지와 별개로 거래된다":"입목법상 등기된 수목과 명인방법을 갖춘 수목은 토지와 별개의 거래 대상이 됩니다.","있으면 잔존한 것에 존재한다(제385조)":"선택할 행위 중 일부가 불능이면 남은 행위에 채권이 존재합니다.","장래 채권도 특정 가능하고 발생이 기대되면 양도할 수 있고, 가압류된 채권도 양도할 수 있다":"앞으로 생길 채권이라도 특정되고 발생할 가능성이 크면 양도할 수 있고 압류 대상 채권도 양도 가능합니다.","장소를 정하지 않으면 특정물 인도는 채권 성립 당시 그 물건이 있던 장소, 그 밖의 채무는 채권자의 현주소에서 한다(제467조)":"변제 장소는 정함이 없으면 특정물은 채권 성립 당시 있던 곳, 그 밖의 채무는 채권자의 현주소입니다.","재산적 손해 배상으로 정신적 고통도 회복된다고 보는 것이 원칙이다":"재산권 침해에서는 재산적 손해를 배상받으면 정신적 고통도 회복된 것으로 보는 것이 원칙입니다.","재판이 확정된 때부터 새로 진행한다(제178조)":"재판상 청구로 중단된 시효는 재판 확정 때부터 새로 시작합니다.","저당물 경매로 토지와 지상건물의 소유자가 달라지면 건물소유자에게 지상권을 설정한 것으로 본다(제366조)":"저당물 경매로 토지와 건물의 소유자가 달라지면 건물 소유자에게 법정지상권이 생긴 것으로 봅니다.","전부무효가 원칙이고(제137조), 무효임을 알고 추인하면 새로운 법률행위로 본다(제139조)":"일부가 무효면 전부 무효가 원칙이고 무효를 알고 추인하면 새 법률행위로 봅니다.","전원 동의, 관리는 지분의 과반수, 보존행위는 각자 한다(제264조·제265조)":"공유물 처분·변경은 전원 동의, 관리는 지분 과반수, 보존행위는 각자 할 수 있습니다.","전원으로부터 또는 전원에 대해 해야 하며 1인의 해제권이 소멸하면 전원에 대해 소멸한다(제547조)":"해제권 행사는 당사자가 여럿이면 전원이 또는 전원에게 해야 하며 1인의 해제권이 소멸하면 전원에 대해 소멸합니다.","전 채무자의 채무에 대한 보증이나 제3자 제공 담보는 그들이 동의하지 않으면 소멸한다(제459조)":"이전 채무자를 위한 보증이나 제삼자 담보는 보증인·담보제공자가 동의하지 않으면 인수 시 사라집니다.","전 채무자의 항변으로 대항할 수 있다":"면책적 인수인은 전 채무자가 가진 항변으로 채권자에게 맞설 수 있습니다.","절대적 무효이므로 제2매수인에게서 다시 산 제3자는 선의라도 소유권을 얻지 못한다":"이 경우는 절대적 무효라서 제2매수인에게서 산 제3자도 선의여도 소유권을 얻지 못합니다.","점유를 옮기지 않고 부동산에서 우선변제를 받는 권리다(제356조)":"저당권은 점유를 넘기지 않고 부동산에서 우선변제를 받는 권리입니다.","점유자는 소유의 의사로 선의·평온·공연하게 점유한 것으로 추정하고(제197조 제1항), 점유자가 행사하는 권리는 적법하게 보유한 것으로 추정한다(제200조)":"점유자는 소유의 의사로 선의·평온·공연하게 점유한 것으로 추정하고 행사하는 권리도 적법하다고 추정합니다.","점유자에게 반환을, 방해자에게 방해제거를, 방해할 염려가 있는 자에게 예방이나 손해배상의 담보를 청구할 수 있다(제213조·제214조)":"소유자는 점유자에게 반환을, 방해자에게 방해제거를, 방해 염려가 있는 자에게 예방이나 담보를 청구합니다.","정관에 기재해야 효력이 있고 등기하지 않으면 제3자에게 대항하지 못한다(제60조)":"이사의 대표권 제한은 정관에 적어야 효력이 있고 등기하지 않으면 제3자에게 맞서지 못합니다.","정관에 해임사유를 정했으면 다른 사유로 해임할 수 없다":"정관으로 해임사유를 정했다면 그 밖의 사유로는 이사를 해임할 수 없습니다.","정관·총회가 금지하지 않은 사항에 한해 특정한 행위만 대리하게 할 수 있고 포괄적 위임은 효력이 없다(제62조)":"이사는 금지되지 않은 사항에 한해 특정 행위만 대리시킬 수 있고 포괄적 위임은 효력이 없습니다.","정식이사와 같은 권한을 가지며 비법인사단에도 유추적용된다":"임시이사는 정식이사와 같은 권한을 갖고 비법인사단에도 유추 적용됩니다.","정지조건은 성취한 때부터 효력이 생기고 해제조건은 성취한 때부터 효력을 잃으며 소급 의사표시가 있으면 그에 따른다(제147조)":"정지조건은 성취한 때부터 효력이 생기고 해제조건은 성취한 때부터 효력을 잃으며 소급 약정이 있으면 따릅니다.","정지조건이면 조건 없는 법률행위, 해제조건이면 무효이고, 불능조건은 그 반대다(제151조)":"기성조건은 정지조건이면 조건 없는 행위, 해제조건이면 무효이고 불능조건은 그 반대입니다.","제2매수인에게 소유권이전등기를 마친 때 이행불능이 되고, 계약 체결만으로는 불능이 아니다":"이중매매에서 제2매수인에게 등기를 마친 때 이행불능이 되고 계약만으로는 불능이 아닙니다.","제2매수인에게 직접 말소를 청구하지 못하고 매도인을 대위하여 청구한다":"첫째 매수인은 둘째 매수인에게 곧바로 말소를 못 구하고 매도인의 권리를 대신 행사하는 방법을 씁니다.","제2매수인이 이중매매 사실을 안 것만으로는 부족하고 매도인의 배임행위에 적극 가담해야 반사회적 법률행위가 된다":"제2매수인이 이중매매임을 아는 것으로는 부족하고 매도인의 배임에 적극 가담해야 무효가 됩니다.","제3자가 제공한 담보는 소멸한다":"임대차가 묵시적으로 갱신되면 제3자가 제공한 담보는 소멸합니다.","제3자와의 약정에 따라 처리한 사무는 원칙적으로 그 타인과의 관계에서 사무관리가 아니고, 본인의 의사에 반함이 명백하면 성립하지 않는다":"제삼자와의 약정으로 처리한 일은 원칙적으로 사무관리가 아니고 본인이 분명히 반대하는 일도 관리가 아닙니다.","제3자의 사기가 아니어서 본인이 몰랐어도 상대방이 취소할 수 있다":"대리인이 속였다면 본인 측 행위로 보아 본인이 몰랐더라도 상대방이 계약을 취소할 수 있습니다.","제3채무자에게 대위채권자 자신에게 직접 이행하라고 청구할 수 있다":"금전·동산을 받아 올 때는 채권자가 직접 자기에게 내놓으라고 제삼채무자에게 요구할 수 있습니다.","제한능력자가 속임수로 능력자로 믿게 하면 취소할 수 없다":"제한능력자가 속임수로 능력자라고 믿게 했다면 법률행위를 취소하지 못합니다.","조건·기한을 붙이지 못하고 상계적상 시로 소급해 소멸한다(제493조)":"상계는 조건이나 기한을 붙이지 못하고 상계적상 때로 소급해 채무를 소멸시킵니다.","조건 성취 전에는 진행하지 않는다":"정지조건부 권리는 조건이 이뤄지기 전에는 시효가 진행하지 않습니다.","조합원의 조합탈퇴권, 임대인의 해지권은 일신전속권이 아니어서 대위할 수 있다":"조합탈퇴권과 임대인의 해지권은 일신전속권이 아니라서 채권자가 대위할 수 있습니다.","존속기간 일수 비율로 취득한다(제102조)":"법정과실은 권리 존속 기간의 일수에 비례해 나누어 취득합니다.","주물의 상용에 이바지하는 독립한 물건으로서 원칙적으로 주물 소유자의 물건이어야 한다(제100조 제1항)":"종물은 주물의 상용에 이바지하는 독립한 물건이며 원칙적으로 주물 소유자의 소유여야 합니다.","주물 자체의 효용을 도와야 하고, 소유자나 이용자의 상용에 쓰일 뿐인 물건은 종물이 아니다":"종물은 주물 자체의 효용을 높여야 하며 소유자의 사용에 쓰일 뿐인 물건은 종물이 아닙니다.","주채무를 따르지 않고 보증채무 자체로 정한다":"보증채무의 시효기간과 연체이율은 주채무와 무관하게 보증채무 자체를 기준으로 합니다.","주채무를 중단시키지 않으며 주채무가 시효로 소멸하면 보증채무는 자체 중단에도 부종성에 따라 소멸한다":"연대보증채무의 시효를 중단해도 주채무는 중단되지 않아 주채무가 소멸하면 보증채무도 부종성으로 사라집니다.","주채무자의 항변으로 대항할 수 있고 주채무자가 항변을 포기해도 보증인에게는 효력이 없다(제433조)":"보증인은 주채무자의 항변으로 맞설 수 있고 주채무자가 항변을 포기해도 보증인에게는 효력이 없습니다.","중단이 없고 원칙적으로 권리가 발생한 때부터 기산하며 법원이 직권으로 조사한다":"제척기간은 중단이 없고 권리 발생 때부터 진행하며 법원이 직권으로 조사합니다.","중단 효력이 없지만 최고의 효력은 남아 6월 내에 재판상 청구 등을 하면 최초 청구 때 중단된 것으로 본다(제170조)":"소가 각하·기각·취하되면 중단은 없지만 최고의 효력은 남아 6월 안에 재판상 청구를 하면 처음 청구 때 중단됩니다.","중도금 미지급 시 최고 없이 해제된다는 실권특약은 효력이 있지만 잔금에 관한 실권특약은 매도인이 이행을 제공해야 해제된다":"중도금 불이행의 실권특약은 최고 없이 해제되지만 잔금의 실권특약은 매도인이 이행을 제공해야 해제됩니다.","중도금을 지급하면 이행 착수이고, 이행 최고나 대금 청구 소송만으로는 착수가 아니다":"계약금 해제를 막는 이행 착수는 중도금 지급 같은 행위이고 최고나 소 제기는 착수로 보지 않습니다.","중도금·잔금 수령과 지급기일 연장 권한이 있지만 합의해제·해제권·의사표시 수령권은 없다":"매도 대리권에는 중도금·잔금 수령과 지급기일 연장이 들어가지만 합의해제와 해제권은 없습니다.","중도금·지연손해금·잔금과 소유권이전의무가 동시이행이 되어 중도금 지연손해금은 잔금기일 이후 생기지 않는다":"중도금을 미루다 잔금기일이 지나면 잔금과 소유권이전이 동시이행이 되어 중도금 지연손해금은 잔금기일 이후 생기지 않습니다.","중 쌍방 책임 없는 사유로 불능이 되면 채무자는 반대급부를 청구할 수 있고, 자기 채무를 면해 얻은 이익은 상환해야 한다(제538조)":"채권자 책임이나 수령지체 중 쌍방 책임 없는 사유로 불능이 되면 채무자는 반대급부를 청구하되 면책 이익은 상환합니다.","증서를 제시한 때부터 지체가 된다":"지시채권·무기명채권·양도성예금증서는 증서를 제시해 청구한 때부터 지체가 됩니다.","증언 대가 약정은 통상 용인되는 수준을 넘을 때만 무효이다":"증언 대가를 약속한 계약은 통상 용인되는 정도를 넘어설 때만 무효입니다.","지상권자는 원상회복의무가 있지만 설정자가 상당한 가액으로 매수를 청구하면 정당한 이유 없이 거절하지 못한다(제285조)":"지상권이 끝나면 지상권자가 원상으로 돌려놓아야 하나 설정자가 상당한 값으로 사겠다고 하면 이를 거절할 수 없습니다.","지연손해금이 아니라 부당이득반환의 성질이다":"해제로 돌려줄 금전에 붙는 이자는 지연손해금이 아니라 부당이득반환의 성질입니다.","직무범위에 속하지 않음을 피해자가 알았거나 중대한 과실로 몰랐으면 법인은 책임을 지지 않는다":"겉보기에 직무 같아도 피해자가 직무가 아님을 알았거나 중과실로 몰랐다면 법인이 책임지지 않습니다.","질권자는 자기 책임으로 전질할 수 있다(제336조)":"질권자는 자기 책임으로 질물을 다시 질권의 목적으로 삼는 전질을 할 수 있습니다.","질물의 멸실 등으로 설정자가 받을 금전에 물상대위할 수 있으나 지급·인도 전에 압류해야 한다(제342조)":"질권은 질물 멸실로 설정자가 받을 금전에 물상대위하려면 지급·인도 전에 압류해야 합니다.","집행보전 효력이 있는 동안 계속되며 본압류로 이행해도 소멸하지 않는다":"가압류의 중단 효력은 집행보전 효력이 지속되는 동안 이어지고 본압류로 옮겨 가도 없어지지 않습니다.","착오로 취소하지 못하지만 당사자 자격이나 분쟁 이외의 사항에 관한 착오는 예외이고(제733조), 사기로 인한 화해는 취소할 수 있다":"화해는 착오로 취소하지 못하나 당사자 자격이나 분쟁 이외 사항의 착오는 예외이고 사기로 인한 화해는 취소할 수 있습니다.","착오 취소는 따로 할 수 있다":"담보책임이 성립하는 경우에도 매수인은 착오 취소를 따로 할 수 있습니다.","채권신고기간 내 변제하지 못하지만 법인은 지연손해 배상의무를 면하지 못하며(제90조), 알고 있는 채권자는 청산에서 제외하지 못한다":"청산인이 기간 내 변제하지 않아도 법인의 지연손해 배상의무는 남고 알고 있는 채권자는 청산에서 뺄 수 없습니다.","채권자가 미리 수령을 거절하거나 채권자의 행위가 필요하면 변제준비 완료를 통지하고 수령을 최고하는 구두제공으로 충분하다(제460조)":"채권자가 미리 받지 않겠다고 하거나 채권자의 협력이 필요할 때는 준비 완료를 알리고 수령을 촉구하면 됩니다.","채권자가 이익을 받은 한도에서 효력이 있다(제472조)":"그 밖의 무권한자에게 한 변제는 채권자가 이익을 받은 한도에서 효력이 있습니다.","채권자가 일부대위자보다 우선한다":"배당에서는 일부대위자보다 채권자가 우선합니다.","채권자대위권, 채권자취소권, 토지거래허가 협력의무 이행청구권도 대위 대상이다":"채권자가 가진 대위권과 취소권, 허가 협력의무 이행청구권까지 채무자 권리를 대신 행사하는 대상이 됩니다.","채권자에게 과실이 있으면 법원은 직권으로 참작하며 당사자가 주장한 비율에 구속되지 않는다(제396조)":"채권자에게 과실이 있으면 법원이 직권으로 참작하며 당사자가 주장한 비율에 묶이지 않습니다.","채권자에게 수령의무가 없으므로 채권자지체만으로 채무불이행책임을 묻지는 못한다":"채권자에게는 수령의무가 없어서 채권자지체만으로 채무불이행책임을 물을 수 없습니다.","채권자와 인수인의 계약에 의한 면책적 인수는 이해관계 없는 제3자가 채무자의 의사에 반해 할 수 없다":"채권자와 인수인이 계약해 채무자를 풀어 주는 인수는 무관한 제삼자가 채무자 뜻에 반해서는 할 수 없습니다.","채권자의 수익 의사표시와 관계없이 공탁공무원의 수탁처분과 공탁물보관자의 수령으로 효력이 생긴다":"변제공탁은 채권자의 수익 의사표시와 상관없이 공탁물보관자의 수령으로 효력이 생깁니다.","채권자의 승낙이 있어야 효력이 생기며 승낙의 상대방은 채무자나 인수인이고, 거절한 뒤에는 다시 승낙해도 효력이 없다(제454조)":"채무자와 인수인의 계약은 채권자의 승낙이 있어야 효력이 생기고 거절한 뒤에는 다시 승낙해도 효력이 없습니다.","채권자의 채무자에 대한 채권이 시효로 소멸했다는 항변은 제3채무자가 원용하지 못한다":"제3채무자는 채권자의 채무자에 대한 채권이 시효로 소멸했다는 항변은 원용할 수 없습니다.","채권 전부를 변제받을 때까지 유치물 전부에 행사한다(제321조)":"유치권은 불가분이라서 채권 전부를 변제받을 때까지 유치물 전부에 행사할 수 있습니다.","채무면제 약정과 병존적 채무인수도 제3자를 위한 계약이다":"채무를 면제해 주기로 한 약정이나 병존적 채무인수는 다른 사람에게 권리를 주는 제삼자를 위한 계약에 속합니다.","채무불이행 사실만 증명하면 되고 손해 발생과 액수는 증명할 필요가 없다":"배상액을 예정해 두면 채권자는 채무불이행 사실만 증명하면 되고 손해 발생과 액수는 증명하지 않아도 됩니다.","채무불이행 손해배상청구권에 대한 시효 항변에 불법행위 청구권의 시효 항변이 포함되지 않는다":"채무불이행 쪽 시효가 지났다는 항변이 있어도 별개 권리인 불법행위 청구권의 시효가 완성됐다는 뜻은 아닙니다.","채무불이행을 이유로 한 해제·해지는 채권자만 할 수 있다(제483조)":"채무불이행을 이유로 한 해제·해지는 일부대위자가 아니라 채권자만 할 수 있습니다.","채무액과 변제기가 특정된 회사 채무를 보증한 이사는 사임을 이유로 해지하지 못한다":"채무액과 변제기가 정해진 회사 채무를 보증한 이사는 사임을 이유로 보증을 해지할 수 없습니다.","채무의 본지에 따른 변제와 유일한 재산을 우선변제권 있는 채권자에게 대물변제한 경우는 원칙적으로 사해행위가 아니다":"채무 내용대로 갚는 변제나 유일한 재산을 담보권자에게 넘기는 대물변제는 다른 채권자를 해친다고 보지 않습니다.","채무의 중요한 부분을 변경하면 경개로 구채무가 소멸한다(제500조)":"채무의 중요한 부분을 바꾸면 경개가 되어 옛 채무가 사라집니다.","채무자가 소멸을 청구할 수 있다":"유치권자가 의무를 어기면 채무자가 유치권의 소멸을 청구할 수 있습니다.","채무자는 그 채무를 수동채권으로 상계하지 못하지만 중과실 불법행위는 금지 대상이 아니며, 피해자는 손해배상채권으로 상계할 수 있다(제496조)":"고의의 불법행위 채무는 수동채권으로 상계할 수 없지만 중과실 불법행위는 금지 대상이 아니고 피해자는 상계할 수 있습니다.","채무자에게 통지하고, 통지 후 채무자의 처분은 채권자에게 대항하지 못한다(제405조)":"보전행위 외의 대위행사는 채무자에게 통지해야 하고 통지 후 채무자의 처분은 채권자에게 대항하지 못합니다.","채무자에 대해 가진 동시이행항변권 등으로 대위채권자에게 대항할 수 있다":"제삼채무자는 채무자에게 있던 동시이행항변권 같은 방어 수단을 대위채권자에게도 그대로 쓸 수 있습니다.","채무자 의사에 반해서도 할 수 있다":"병존적 인수는 채무자의 의사에 반해서도 할 수 있습니다.","채무자의 악의는 채권자가 증명하고 수익자의 악의는 추정된다":"사해행위 취소소송에서 채무자가 해칠 의사가 있었음은 채권자가 입증하고 수익자의 악의는 법이 추정합니다.","채무자의 이익으로 추정하며(제153조), 기한이익 상실특약은 형성권적 특약으로 추정한다":"기한은 채무자를 위한 것으로 추정되고 기한이익을 잃는 특약은 형성권적인 것으로 추정됩니다.","처분 당시의 대가를 반환한다":"원물을 처분해 돌려줄 수 없으면 처분 당시의 대가를 반환합니다.","처분의 능력이나 권한이 필요 없다(제177조)":"승인은 처분 능력이나 권한이 없어도 할 수 있어 시효 중단 효과가 있습니다.","청구, 압류·가압류·가처분, 승인이 중단사유다(제168조)":"시효 중단 사유는 청구, 압류·가압류·가처분, 승인입니다.","청구할 수 있으나 과실을 취득했으면 통상의 필요비는 청구하지 못한다(제203조)":"점유자는 필요비를 청구할 수 있으나 과실을 취득했다면 통상의 필요비는 청구하지 못합니다.","청산사무가 남아 있으면 법인은 소멸하지 않는다":"청산종결등기를 했더라도 청산사무가 남아 있으면 법인은 소멸하지 않습니다.","청약 거절과 새 청약으로 본다(제534조)":"조건을 붙이거나 변경한 승낙은 청약의 거절이면서 새로운 청약으로 봅니다.","청약의 유인이면 피유인자의 청약에 분양자가 승낙해야 계약이 성립한다":"분양광고가 청약의 유인이면 상대방의 청약에 분양자가 승낙해야 계약이 성립합니다.","청약의 효력에는 영향이 없다":"청약자가 발송 후 도달 전에 사망해도 청약의 효력에는 영향이 없습니다.","초과분이나 특별손해를 따로 청구하지 못하고, 예정은 불법행위 손해까지 포함하지 않으며 과실상계도 하지 않는다":"실손해가 예정액보다 커도 초과분을 따로 청구할 수 없고 예정은 불법행위 손해를 포함하지 않으며 과실상계도 하지 않습니다.","초일을 산입하지 않고 오전 0시부터 시작하면 산입한다(제157조)":"일·주·월·연 단위 기간은 초일을 넣지 않지만 오전 0시에 시작하면 초일을 넣습니다.","총유물 관리·처분행위가 아니어서 총회 결의 없이 해도 유효하다":"타인 채무를 보증하는 것은 총유물의 관리·처분이 아니라서 총회 결의 없이 해도 유효합니다.","최고액만 정하고 채무 확정을 장래에 보류하며 이자는 최고액에 산입한 것으로 본다(제357조)":"근저당은 채권 최고액만 정하고 채무 확정을 장래로 미루며 이자는 최고액에 포함된 것으로 봅니다.","최고 없이 불법행위 시부터 지체가 된다":"불법행위 손해배상채무는 최고 없이 불법행위 때부터 지체가 됩니다.","최고 없이 해제한다(제546조)":"이행불능이면 최고 없이 바로 계약을 해제할 수 있습니다.","추인으로 유효가 될 수 없으나 무효행위 전환(제138조)은 가능하며 그 계약의 부제소합의도 무효다":"불공정 법률행위는 추인해도 유효가 되지 않으나 무효행위 전환은 가능하고 부제소합의도 무효입니다.","추인을 거절하는 것은 신의칙에 반한다":"무권대리인을 단독상속한 본인이 추인을 거절하면 신의칙에 반합니다.","추인할 수 있는 날부터 3년, 법률행위를 한 날부터 10년 내에 행사하며 이는 제척기간이다(제146조)":"취소권은 추인할 수 있는 날부터 3년, 행위일부터 10년 안에 행사해야 하는 제척기간입니다.","출생일을 산입해 만 나이로 계산하고 1세 미만은 월수로 표시할 수 있다(제158조)":"나이는 출생일을 넣어 만 나이로 따지고 1세 미만은 월수로 나타낼 수 있습니다.","출자는 노무로도 할 수 있고 조합계약은 해제할 수 없으며 조합원 1인을 채무자로 한 가압류로 조합재산을 집행하지 못한다":"조합 출자는 일을 해 주는 것도 가능하고 조합계약은 해제할 수 없으며 조합원 한 명의 가압류는 조합재산에 미치지 않습니다.","취소권은 재판상으로만 행사하고 피고는 수익자나 전득자이며 채무자는 피고적격이 없다":"채권자취소권은 소송으로만 행사하고 피고는 수익자나 전득자이며 채무자는 피고가 될 수 없습니다.","취소 대상은 채무자와 수익자 사이의 행위다":"전득자를 상대로 소를 내도 취소 대상은 채무자와 수익자 사이의 행위입니다.","취소만 먼저 구하고 원상회복을 나중에 청구할 수도 있다":"사해행위 취소만 먼저 구하고 원상회복은 나중에 따로 청구할 수 있습니다.","취소원인을 안 날부터 1년, 법률행위가 있은 날부터 5년 내에 제기하며(제406조) 제척기간 도과는 상대방이 증명한다":"제소기간은 취소원인을 안 날부터 1년, 행위일부터 5년이며 도과는 상대방이 증명해야 합니다.","취소의 효력은 채권자와 수익자 사이에서만 생겨 채무자가 권리를 다시 얻지 않으므로 채무자를 대위해 청구할 수 없다":"취소 효력은 채권자와 수익자 사이에서만 생기고 채무자는 권리를 되찾지 않으므로 채무자를 대위해 청구하지 못합니다.","취소채권자에게 직접 인도를 청구할 수 있다":"사해행위의 목적이 동산이면 취소채권자에게 직접 인도를 청구할 수 있습니다.","취소·해제 후 쌍방의 원상회복의무, 임대차 종료 시 목적물반환과 보증금반환, 건물매수청구 후 건물 인도·등기와 대금 지급, 하자보수에 갈음한 손해배상과 보수 지급, 해제 시 가등기말소와 대금반환":"취소·해제 후 원상회복, 임대차 종료 때 반환과 보증금, 건물매수청구 후 인도와 대금 등은 동시이행 관계입니다.","타인의 물건을 점유한 자가 그 물건에 관하여 생긴 채권이 변제기에 있으면 변제받을 때까지 유치할 수 있다":"유치권은 남의 물건을 점유한 사람이 그 물건에서 생긴 채권의 변제를 받을 때까지 물건을 잡아 두는 권리입니다.","타인의 토지를 자기 토지의 편익에 이용하는 권리다(제291조)":"지역권은 남의 토지를 자기 토지의 편익에 이용하는 권리입니다.","태아는 사인증여를 받을 수 없고, 법인은 포괄적 유증을 받을 수 있으며 반려동물은 권리주체가 아니다":"권리능력은 사람과 법인에게 있어 동물은 주체가 아니며 태아에게는 사인증여를 못 하고 법인에게는 포괄유증이 가능합니다.","토지와 그 정착물은 부동산이고 부동산 외의 물건은 모두 동산이다(제99조)":"부동산은 토지와 그 정착물이고 부동산이 아닌 물건은 모두 동산입니다.","토지 저당 후 설정자가 건물을 지으면 저당권자는 건물도 함께 경매할 수 있지만 건물 대가에서는 우선변제를 받지 못한다(제365조)":"토지 저당 후 설정자가 지은 건물도 함께 경매할 수 있으나 건물 대가에서는 우선변제를 받지 못합니다.","특별손해이고 배상액은 이행불능 당시 시가가 기준이다":"이행불능 후 가격 상승분은 특별손해이고 배상액은 이행불능 당시 시가가 기준입니다.","특약이 있어야 청구하지만 변호사에게는 묵시적 보수 약정이 인정된다":"위임 보수는 특약이 있어야 요구하는 것이 원칙이나 변호사는 말하지 않아도 보수 약정이 있었다고 봅니다.","특정 내용의 의사표시를 하려는 생각이지 마음속 바람이 아니다":"비진의표시의 진의는 일정 내용의 의사표시를 하려는 생각이지 마음속 바람이 아닙니다.","특정할 수 있으면 증감·변동하는 유동집합물도 하나의 물건이 된다":"증감하는 물건의 집합이라도 특정할 수 있으면 하나의 물건으로 거래할 수 있습니다.","판결·지급명령·화해 등으로 확정된 채권은 단기시효라도 10년이 된다(제165조)":"판결이나 지급명령, 화해로 확정된 채권은 원래 단기시효라도 10년으로 늘어납니다.","평온·공연하게 동산을 양수한 자가 선의·무과실로 점유하면 양도인이 무권리자여도 즉시 소유권을 취득한다(제249조)":"선의취득은 평온·공연한 양수인이 선의·무과실이면 양도인이 무권리자여도 곧바로 소유권을 얻습니다.","품질을 정할 수 없으면 중등품질로 이행하고, 이행에 필요한 행위를 완료하거나 채권자 동의로 지정하면 그 물건으로 특정된다(제375조)":"종류채권은 품질을 정할 수 없으면 중등품질로 이행하고 이행 행위를 마치거나 동의로 지정하면 특정됩니다.","피보전채권의 시효소멸을 원용할 수 있다":"수익자는 피보전채권이 시효로 소멸했다고 원용할 수 있습니다.","피상속인이 유언으로 자신의 유체를 처분했더라도 제사주재자가 이에 따라야 할 법적 의무는 없다":"유체의 귀속은 제사주재자에게 있어 고인의 유언과 달라도 제사주재자가 따를 의무는 없습니다.","피용자와 같은 범위의 책임을 지므로 공동불법행위자들의 과실비율과 관계없이 피용자가 질 전액을 배상한다":"사용자의 책임은 피용자와 같은 범위여서 공동행위자 사이 과실비율과 상관없이 피용자 몫 전부를 갚아야 합니다.","피해자의 과실을 전원에 대해 전체적으로 평가하고, 고의로 피해자 부주의를 이용한 자가 있어도 그렇지 않은 자는 과실상계를 주장할 수 있다":"공동불법행위에서는 피해자의 과실을 전원에 대해 전체로 평가하고 고의로 이용한 자가 있어도 다른 자는 과실상계를 주장할 수 있습니다.","필요비는 즉시, 유익비는 종료 시 가액 증가가 현존할 때 상환받는다(제626조)":"임차인은 필요비를 즉시, 유익비를 종료 시 가액 증가가 남아 있을 때 상환받습니다.","필요비·유익비 상환을 청구할 수 있고, 본인 의사에 반해 관리했으면 현존이익 한도로 줄어든다(제739조)":"관리자는 필요비·유익비 상환을 청구할 수 있으나 본인 의사에 반했다면 현존이익 한도로 줄어듭니다.","하자를 알고 고지하지 않은 경우가 아니면 지지 않는다":"증여자는 하자를 알고도 알리지 않은 경우가 아니면 담보책임을 지지 않습니다.","한도로 하고 특별손해는 채무자가 그 사정을 알았거나 알 수 있었을 때만 배상하며(제393조)":"손해배상은 통상손해를 한도로 하고 특별손해는 채무자가 그 사정을 알았거나 알 수 있을 때만 배상합니다.","합유자 전원의 동의가 필요하다(제272조)":"합유물을 처분·변경하려면 합유자 전원의 동의가 필요합니다.","합의 충당이 가장 우선하고, 다음으로 변제자가 지정하며 변제자가 지정하지 않으면 변제받는 자가 지정한다(제476조)":"변제충당은 합의가 가장 우선하고 다음으로 변제자가 지정하며 지정이 없으면 받는 사람이 지정합니다.","해제권자의 가공·개조로 목적물이 다른 종류가 되면 해제권은 소멸한다(제553조)":"해제권자가 가공·개조해 목적물이 다른 종류가 되면 해제권이 소멸합니다.","해제는 손해배상청구에 영향이 없고(제551조) 이행이익 배상이 원칙이나, 약정해제권 행사에는 손해배상이 따르지 않는다":"해제해도 손해배상청구는 가능하고 이행이익 배상이 원칙이나 약정해제권 행사에는 손해배상이 따르지 않습니다.","해제는 철회하지 못하고(제543조)":"해제의 의사표시는 철회하지 못합니다.","해제 전에 등기·압류 등으로 완전한 권리를 얻은 자이고, 계약상 채권 자체의 양수인·압류자는 포함되지 않으며 해제 후 이해관계인은 선의여야 한다":"해제의 효과를 막을 수 있는 제삼자는 해제 전에 등기·압류 등으로 완전한 권리를 얻은 사람입니다.","해지통고로 소멸한 경우에도 인정되고, 미등기 무허가 건물이나 저당권 설정 건물도 대상이며 철거 특약은 무효다(제643조·제652조)":"토지 임차인의 지상물매수청구권은 해지통고로 소멸한 경우에도 인정되고 미등기 무허가 건물도 대상이며 철거 특약은 무효입니다.","행사기간 약정이 없으면 예약 성립 시부터 10년이 지나면 소멸한다":"매매예약완결권은 행사기간을 정하지 않았다면 예약이 성립한 때부터 10년이 지나면 소멸합니다.","행위능력자일 필요가 없다(제117조)":"대리인은 제한능력자여도 되므로 행위능력자일 필요가 없습니다.","현실인도 외에 간이인도, 점유개정, 목적물반환청구권의 양도가 있다":"동산 인도의 방법은 직접 건네는 현실인도 외에 간이인도, 점유개정, 반환청구권 양도 세 가지가 더 있습니다.","환매기간은 부동산 5년, 동산 3년을 넘지 못하고 매매등기와 동시에 환매 보류를 등기해야 제3자에게 효력이 있다(제591조·제592조)":"환매는 부동산 5년, 동산 3년의 기간을 넘길 수 없고 매매등기와 함께 보류를 등기해야 제삼자에게 맞섭니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
